def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: number of nanoseconds since midnight
    :param tz: optional tzinfo object
    :return: datetime.time instance
    """
    import datetime

    # Accept None as a signal to return None
    if nanoseconds is None:
        return None

    try:
        ns = int(nanoseconds)
    except Exception as exc:
        raise ValueError("nanoseconds must be an integer or convertible to int") from exc

    # A day in nanoseconds
    ns_per_day = 24 * 3600 * 1_000_000_000
    if ns < 0 or ns >= ns_per_day:
        raise ValueError("nanoseconds must be in the range [0, %s)" % ns_per_day)

    hour = ns // (3600 * 1_000_000_000)
    ns -= hour * 3600 * 1_000_000_000
    minute = ns // (60 * 1_000_000_000)
    ns -= minute * 60 * 1_000_000_000
    second = ns // 1_000_000_000
    ns -= second * 1_000_000_000
    microsecond = ns // 1_000  # discard remaining nanoseconds less than microsecond

    if tz is not None:
        if not isinstance(tz, datetime.tzinfo):
            raise TypeError("tz must be a datetime.tzinfo instance")
        return datetime.time(hour, minute, second, microsecond, tzinfo=tz)
    else:
        return datetime.time(hour, minute, second, microsecond)

