    if not hasattr(self, "_keys") or not hasattr(self, "_values"):
        raise AttributeError("Record missing _keys and/or _values attributes")
    total = len(self._keys)

    # If no keys are specified, return all name-value pairs
    if not keys:
        return {name: value for name, value in zip(self._keys, self._values)}

    result = {}
    for k in keys:
