def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer. """
    if not hasattr(self, 'data') or not isinstance(self.data, (bytes, bytearray)):
        raise AttributeError("Instance must have a 'data' attribute of type bytes or bytearray.")
    if len(self.data) < 2:
        raise ValueError("Insufficient data: cannot pop 2 bytes from an empty or too-short buffer.")
    last_bytes = self.data[-2:]
    del self.data[-2:]
    return int.from_bytes(last_bytes, byteorder='big', signed=False)

def pop_u16(self):
    """
    Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Try to retrieve the buffer; assume it's stored in self.data
    try:
        buffer = self.data
    except AttributeError:
        raise AttributeError("The object does not have a 'data' attribute.")

    if buffer is None:
        raise ValueError("Data buffer is None")

    # Ensure we have at least two bytes
    if len(buffer) < 2:
        raise ValueError("Not enough data to pop 2 bytes")

    # Extract and remove the last two bytes
    last_two = buffer[-2:]

    if isinstance(buffer, bytearray):
        # Modify in place if possible
        del buffer[-2:]
    else:
        # For immutable types create a new slice
        self.data = buffer[:-2]

    # Convert bytes to unsigned integer (big-endian)
    return int.from_bytes(last_two, byteorder='big')

