def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    ``name`` must be a valid identifier for the class name.
    ``fields`` should be an iterable of field names (strings).  Each field
    will be added as an attribute of the created class.
    ``srid_map`` is a mapping from field names to SRID values and is
    stored on the class as ``_srid_map``.
    The resulting class inherit from ``shapely.geometry.Point`` if the
    library is available, otherwise from :class:`object`.
    """
    # Validate ``name``.
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f"Class name must be a valid identifier, got {name!r}")

    # Validate ``fields``.
    if fields is None:
        fields = []
    try:
        field_iter = iter(fields)
    except TypeError as exc:
        raise TypeError(f"'fields' must be iterable, got {fields!r}") from exc

    field_names = []
    for f in field_iter:
        if not isinstance(f, str):
            raise TypeError(f"Field names must be strings, got {f!r}")
        if not f.isidentifier():
            raise TypeError(f"Invalid field name {f!r}: must be a valid identifier")
        if f in field_names:
            raise TypeError(f"Duplicate field name: {f!r}")
