def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Split the input string by dots and convert each numeric component to an
    integer. Non‐numeric components are ignored. Leading and trailing
    whitespace is stripped. If the input is not a string a ``TypeError`` is
    raised.

    Args:
        s: The version string to parse.

    Returns:
        A tuple of integers representing the version components.
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected a string for version, got {type(s).__name__!r}")

    s = s.strip()
    if not s:
        return ()

    parts: list[int] = []
    for component in s.split('.'):
        if component == "":
            continue
        try:
            parts.append(int(component))
        except ValueError:
            # Attempt to extract leading digits from a component like '2b'
            digits = "".join(ch for ch in component if ch.isdigit())
            if digits:
                parts.append(int(digits))
            # otherwise ignore non-numeric component
    return tuple(parts)

