def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    import os
    import traceback

    if e is None:
        return ''
    if not isinstance(e, BaseException):
        return str(e)

    # Use the traceback from the exception instance if available.
    tb = getattr(e, '__traceback__', None)
    if tb is None:
        # If no traceback, attempt to use sys.exc_info()
        try:
            import sys
            exc_type, exc_value, exc_tb = sys.exc_info()
            tb = exc_tb
        except Exception:
            tb = None

    lines = []
    # If a traceback is available, format a limited stack trace
    if tb is not None:
        stack = traceback.extract_tb(tb)
        # limit to max_level items from the bottom of the stack
        if len(stack) > max_level:
            stack = stack[-max_level:]
        for frame in stack:
            filename = frame.filename or '<unknown>'
            # truncate path components if too long
            parts = filename.split(os.sep)
            if len(parts) > max_path_level:
                filename = os.sep.join(parts[-max_path_level:])
            lines.append(f'{frame.name} (file "{filename}", line {frame.lineno})')
            if frame.line:
                lines.append(f'  {frame.line.strip()}')
    else:
        # No traceback: just show exception type and message
        lines.append(f'{type(e).__name__}: {e}')

    # Add exception message
    if isinstance(e, Exception):
        msg = str(e)
        if msg and not lines[-1].endswith(msg):
            lines.append(msg)

    return '\n'.join(lines)

