@classmethod
def _reset_logging(cls):
    """
    Reset
    """
    try:
        root = logging.getLogger()
        # Remove all existing handlers
        for handler in root.handlers[:]:
            try:
                root.removeHandler(handler)
                handler.close()
            except Exception:
                pass
        # Reconfigure root logger with default settings
        logging.basicConfig(level=logging.WARNING, handlers=[logging.StreamHandler()])
    except Exception as exc:
        # If any error occurs during resetting, log it using a fallback logger
        fallback_logger = logging.getLogger("fallback")
        if not fallback_logger.handlers:
            fallback_logger.addHandler(logging.StreamHandler())
            fallback_logger.setLevel(logging.ERROR)
        fallback_logger.error("Failed to reset logging configuration: %s", exc)

@classmethod
def _reset_logging(cls):
    """Reset"""
    try:
        import logging
        # Get the root logger
        root = logging.getLogger()
        # Remove all handlers from the root logger
        for handler in root.handlers[:]:
            try:
                root.removeHandler(handler)
                if hasattr(handler, "close"):
                    handler.close()
            except Exception:
                pass  # ignore individual handler errors
        # Reconfigure the root logger with the default settings
        # If no specific level/format is desired, we use WARNING as a sane default
        logging.basicConfig(level=logging.WARNING, format='%(levelname)s:%(name)s:%(message)s')
        # Ensure the root logger has at least one handler
        if not root.handlers:
            root.addHandler(logging.StreamHandler())
        # Reset all other loggers in the logger manager
        manager = logging.Logger.manager
        for logger_name, logger_obj in manager.loggerDict.items():
            if isinstance(logger_obj, logging.Logger):
                for h in logger_obj.handlers[:]:
                    try:
                        logger_obj.removeHandler(h)
                        if hasattr(h, "close"):
                            h.close()
                    except Exception:
                        pass
                logger_obj.setLevel(logging.WARNING)
    except Exception as e:
        # In case of any unexpected error, re-raise with a clear message
        raise RuntimeError(f"Failed to reset logging: {e}") from e

