def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    result = []
    for candidate in classes:
        if candidate is None:
            continue
        if not isinstance(candidate, type):
            raise TypeError(f"{candidate!r} is not a class")

        # Skip if candidate is already covered by an existing class in result
        if any(issubclass(existing, candidate) for existing in result):
            continue

        # Remove any existing class that is a subclass of candidate
        result = [existing for existing in result if not issubclass(candidate, existing)]

        # Append candidate if not already present (duplicates)
        if candidate not in result:
            result.append(candidate)

    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        return []
    # Ensure iterable
    try:
        iter(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of class objects")
    seen = set()
    result_rev = []
    for cls in reversed(list(classes)):
        if not isinstance(cls, type):
            raise TypeError(f"element {cls!r} is not a class")
        # Skip if any already kept class is a subclass of this candidate
        if any(issubclass(other, cls) for other in seen):
            continue
        seen.add(cls)
        result_rev.append(cls)
    return list(reversed(result_rev))

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("`classes` must be a list or tuple of class objects")
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Expected a class type, got {type(cls).__name__}")
        if cls in result:
            continue
        skip = False
        for kept in result:
            # If an earlier kept base is a subclass of the current one,
            # the current base is redundant
            try:
                if issubclass(kept, cls):
                    skip = True
                    break
            except Exception:
                # In case issubclass fails due to incorrect types/data
                continue
        if not skip:
            result.append(cls)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    results = []
    for name in dir(self):
        # Skip private, special, and descriptor attributes
        if name.startswith('_'):
            continue
        try:
            attr = getattr(self, name)
        except Exception:
            continue
        # Try to get documentation from the attribute or its descriptor
        doc = getattr(attr, "__doc__", None)
        # Some attributes may be property objects; get doc from fget if possible
        if doc is None and hasattr(attr, "fget"):
            doc = getattr(attr.fget, "__doc__", None)
        if doc is None:
            # No docstring available
            if all:
                results.append((name, ""))
            continue
        # If the docstring is empty or just whitespace, skip unless all is True
        if not all and not doc.strip():
            continue
        results.append((name, doc.strip()))
    return results

