    # Inspect all members of the class
    for name, member in inspect.getmembers(cls):
        # Skip private and protected members unless 'all' is True
        if not all and name.startswith('_'):
            continue

        # Skip methods and static/class methods
        if inspect.isroutine(member):
            continue

        # Attempt to obtain a description
        desc = ""

        # Handle properties specially
        if isinstance(member, property):
            getter = member.fget
            if getter and getter.__doc__:
                desc = getter.__doc__.strip()
        else:
            # Use the member's __doc__ if available
            if hasattr(member, "__doc__"):
                try:
                    doc = member.__doc__
                    if isinstance(doc, str):
                        desc = doc.strip()
                except Exception:
                    pass

        descriptions[name] = desc

    return descriptions

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    names = []
    seen = set()

    # Include instance-specific attributes
    try:
        for name in getattr(self, "__dict__", {}):
            if not all and name.startswith("_"):
                continue
            if name not in seen:
                seen.add(name)
                names.append(name)
    except Exception:
        pass

    try:
        cls = getattr(self, "__class__", type(self))
        # Class-defined attributes
        for name, value in getattr(cls, "__dict__", {}).items():
            if not all and name.startswith("_"):
                continue
            if callable(value):
                continue
            if name not in seen:
                seen.add(name)
                names.append(name)
        # Include inherited attributes if requested
        if all:
            for base in getattr(cls, "__mro__", ()):
                for name, value in getattr(base, "__dict__", {}).items():
                    if name.startswith("_"):
                        continue
                    if callable(value):
                        continue
                    if name not in seen:
                        seen.add(name)
                        names.append(name)
    except Exception:
        pass

    return names

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    names_list = []
    try:
        # If all is True, include attributes from the entire Method Resolution Chain
        if all:
            for cls in self.__class__.__mro__:
                if cls is object:
                    continue
                names_list.extend(
                    name for name, val in cls.__dict__.items()
                    if not name.startswith('_') and not callable(val)
                )
        else:
            names_list.extend(
                name for name, val in self.__class__.__dict__.items()
                if not name.startswith('_') and not callable(val)
            )
    except Exception:
        # In case any unexpected error occurs, return an empty list
        return []

    # Ensure uniqueness while preserving declaration order
    seen = set()
    unique_names = []
    for name in names_list:
        if name not in seen:
            seen.add(name)
            unique_names.append(name)
    return unique_names

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("The 'all' parameter must be a boolean.")
    # Retrieve the attributes defined directly on this class
    class_attrs = getattr(self, "__class__", None).__dict__
    if class_attrs is None:
        return []
    names = []
    for name, value in class_attrs.items():
        # Skip private and dunder names
        if name.startswith("_"):
            continue
        # When all=False, skip callable members (methods)
        if not all and callable(value):
            continue
        names.append(name)
    return sorted(names)

