    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Handle potential `Broken` in bases
    bases = getattr(sequence, "__bases__", ())
    try:
        if Broken in bases:
            # If the sequence is a broken component, we treat it as a leaf
            return [sequence]
    except NameError:
        # `Broken` is not defined in this context, ignore
        pass

    cls = sequence.__class__
    mro = getattr(cls, "__mro__", ())

    # Check for interface classes or implements specs
    try:
        if InterfaceClass in mro or zope.interface.declarations.Implements in mro:
            output.append(sequence)
            return output
    except NameError:
        # `InterfaceClass` or `zope.interface.declarations.Implements` not available,
        # fall back to recursion logic
        pass

    # Recursively normalize iterable sequences
    try:
        for v in sequence:
            _normalizeargs(v, output)
    except TypeError:
        # Not iterable: treat as a leaf node
        output.append(sequence)

    return output

