def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context to an empty dictionary
    if hasattr(self, "context") and isinstance(self.context, dict):
        self.context.clear()
    elif hasattr(self, "ctx") and isinstance(self.ctx, dict):
        self.ctx.clear()
    else:
        # If no context attribute, create a new one
        self.context = {}

    # Find the bins attribute (common names)
    bins_attr = None
    for name in ("bins", "_bins", "count", "values", "data"):
        if hasattr(self, name):
            bins_attr = name
            break

    # If no bins found, nothing more to reset
    if bins_attr is None:
        return

    bins = getattr(self, bins_attr)

    # Determine new bins content
    try:
        # If an initial_value is defined and not None, use it
        init_val = getattr(self, "initial_value", None)
        if init_val is not None:
            if isinstance(bins, (list, tuple)):
                new_bins = [init_val for _ in bins]
            else:
                # Try to construct a new container of the same type
                new_bins = type(bins)(len(bins)) * init_val
        elif hasattr(self, "make_bins") and callable(self.make_bins):
            new_bins = self.make_bins()
        else:
            # Default: clear or reset to empty compatible type
            if isinstance(bins, list):
                new_bins = []
            else:
                new_bins = type(bins)()
    except Exception:
        # Fallback: just reset to empty container of the same type
        new_bins = type(bins)()

    # Assign the new bins back to the attribute
    setattr(self, bins_attr, new_bins)

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary to an empty state
    try:
        self.context = {}
    except AttributeError:
        # The object doesn't have a context attribute; ignore
        pass

    # Reinitialize the histogram bins
    try:
        # If an explicit initial_value is defined, use it for all bins
        if hasattr(self, "initial_value"):
            # Determine the number of bins that should exist
            nbins = getattr(self, "nbins", None)
            if nbins is None:
                # Fallback: infer number of bins from an existing bins list, if present
                current_bins = getattr(self, "bins", None)
                nbins = len(current_bins) if current_bins is not None else 0
            # Create new bins with the initial value
            self.bins = [self.initial_value for _ in range(nbins)]
        # If no initial_value, use the make_bins() method if available
        elif hasattr(self, "make_bins") and callable(self.make_bins):
            self.bins = self.make_bins()
        else:
            # No explicit way to reinitialize; fall back to an empty list
            self.bins = []
    except Exception as exc:
        # Provide a clear error message while ensuring the program can continue
        raise RuntimeError(f"Failed to reinitialize histogram bins: {exc}") from exc

    # Optional: reset auxiliary metadata if present
    for attr in ("total_count", "min_value", "max_value"):
        if hasattr(self, attr):
            try:
                if attr == "total_count":
                    setattr(self, attr, 0)
                else:
                    setattr(self, attr, None)
            except Exception:
                # Ignore errors when resetting optional attributes
                pass
    return

def reset(self):
