def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    lines = []
    if header is not None:
        lines.append(str(header))
    for point in self:
        # Determine coordinate and value(s)
        if isinstance(point, (tuple, list)):
            # If point is a two-element tuple where first is coordinate tuple
            if len(point) == 2 and isinstance(point[0], (tuple, list)):
                coords = point[0]
                value = point[1]
            else:
                # Assume last item is value, rest are coordinates
                coords = point[:-1]
                value = point[-1]
        else:
            # Unsupported representation, skip
            continue

        # Convert coordinates to strings
        coord_strs = []
        if isinstance(coords, (tuple, list)):
            for c in coords:
                try:
                    coord_strs.append(str(c))
                except Exception as e:
                    coord_strs.append(f"<error:{e}>")
        else:
            # Single coordinate
            coord_strs.append(str(coords))

        # Convert value(s) to strings
        value_strs = []
        if isinstance(value, (tuple, list)):
            for v in value:
                try:
                    value_strs.append(str(v))
                except Exception as e:
                    value_strs.append(f"<error:{e}>")
        else:
            try:
                value_strs.append(str(value))
            except Exception as e:
                value_strs.append(f"<error:{e}>")

        # Combine and join
        line = separator.join(coord_strs + value_strs)
        lines.append(line)

    if not lines:
        return ""
    return "\n".join(lines) + "\n"

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    lines = []
    if header is not None:
        if not isinstance(header, str):
            raise TypeError("header must be a string or None")
        lines.append(header)
    for point in self:
        # Try to get coordinate and value
        coord = None
        value = None
        if isinstance(point, tuple) and len(point) == 2:
            coord, value = point
        else:
            if hasattr(point, "coordinate") and hasattr(point, "value"):
                coord, value = point.coordinate, point.value
            elif hasattr(point, "coord") and hasattr(point, "val"):
                coord, value = point.coord, point.val
            else:
                # Fallback: treat point as iterable of (coord, value)
                try:
                    coord, value = point
                except Exception:
                    # Unable to parse point; skip
                    continue
        # Convert coordinate to string representation
        if isinstance(coord, (list, tuple)):
            coord_parts = [str(c) for c in coord]
            coord_str = separator.join(coord_parts)
        else:
            coord_str = str(coord)
        # Convert value parts
        value_strs = []
        if isinstance(value, (list, tuple)):
            for v in value:
                value_strs.append(str(v))
        else:
            # Value is a scalar or non-iterable
            value_strs.append(str(value))
        # Build line
        line = separator.join([coord_str] + value_strs)
        lines.append(line)
    return "\n".join(lines) + ("\n" if lines and not lines[-1].endswith("\n") else "")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input type
    if not isinstance(coord_name, str):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

    # Attempt to retrieve the error indices mapping
    try:
        err_mapping = self._err_indices  # expecting a dict-like container
    except AttributeError:
        # The object doesn't hold error indices; return an empty array
        return np.array([], dtype=int)

    # If no error mapping for this coordinate, return empty array
    try:
        idx = err_mapping[coord_name]
    except KeyError:
        return np.array([], dtype=int)

    # Ensure the retrieved indices are array-like
    if isinstance(idx, (list, np.ndarray)):
        return np.asarray(idx, dtype=int)
    else:
        raise ValueError(f"Error indices for coordinate '{coord_name}' must be list or array, got {type(idx).__name__}")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Ensure the coordinate exists in the object's variables
    if coord_name not in getattr(self, "_variables", {}):
        raise KeyError(
            f"Coordinate '{coord_name}' not found in available variables."
        )
    var = self._variables[coord_name]

    # Attempt to locate the error array
    err = None
    # Common attribute names for error information
    if hasattr(var, "err"):
        err = var.err
    elif hasattr(var, "errors"):
        err = var.errors
    elif hasattr(var, "attrs"):
        err = var.attrs.get("err", None) or var.attrs.get("errors", None)

    # If no error information is present, return an empty list
    if err is None:
        return []

    # Convert to a NumPy array for consistent handling
    try:
        err_arr = np.asarray(err)
    except Exception as exc:  # pragma: no cover
        raise ValueError(
            f"Error data for coordinate '{coord_name}' could not be "
            f"converted to an array: {exc}"
        )

    # Determine indices of valid error values
    if err_arr.ndim == 0:
        # Scalar error: consider index 0 if non-zero
        return [0] if err_arr.item() != 0 else []

    # Use a mask: error values that are not NaN and non-zero
    with np.errstate(all="ignore"):
        mask = ~np.isnan(err_arr) & (err_arr != 0)

    # Flatten to 1D if necessary
    if mask.ndim > 1:
        mask = mask.ravel()

    indices = np.where(mask)[0]
    return indices.tolist()

def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        # Attempt to fetch the error array for the specified coordinate.
        try:
            err_arr = np.asarray(self.errors[coord_name])
        except (AttributeError, KeyError, TypeError):
            # If the attributes don't exist or the key isn't present, return an empty list.
            return []

        # If the array is empty return empty list.
        if err_arr.size == 0:
            return []

        # Create a mask for valid error entries.
        # 1) For boolean arrays use the truth value directly.
        # 2) For numeric arrays consider non‑nan and positive values as valid error indices.
        if err_arr.dtype.kind in {'b', 'bool'}:
            mask = err_arr
        else:
            mask = ~np.isnan(err_arr) & (err_arr > 0)

        # Return the indices where the mask is True as a plain list.
        return np.where(mask)[0].tolist()

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    bins = np.asarray(bins)

    # Handle multi‑dimensional edges passed as a sequence of arrays
    if isinstance(edges, (list, tuple)):
        if len(edges) == 0:
            raise ValueError("edges cannot be empty when passed as a sequence.")
        edge_arrs = [np.asarray(e) for e in edges]

        if len(edge_arrs) != bins.ndim:
            raise ValueError(
                f"Number of edge arrays ({len(edge_arrs)}) must match "
                f"the number of bin dimensions ({bins.ndim})."
            )

        for dim, e in enumerate(edge_arrs):
            if e.size != bins.shape[dim] + 1:
                raise ValueError(
                    f"Edge array {dim} length ({e.size}) does not match "
                    f"bins shape along that dimension ({bins.shape[dim]} + 1)."
                )

        # Compute the width of each bin in every dimension
        widths = [np.diff(e) for e in edge_arrs]

        # Broadcast the widths across all dimensions to form the volume element
        vol = widths[0]
        for w in widths[1:]:
            vol = vol[..., None] * w

        return (bins * vol).sum()

    # Otherwise assume edges is a single 1‑D array of bin edges
    edges = np.asarray(edges)
    if edges.size != bins.shape[0] + 1:
        raise ValueError(
            f"edges length ({edges.size}) must be bins length ({bins.shape[0]}) + 1."
        )
    width = np.diff(edges)
    return (bins * width).sum()

