    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dictionary")
    # d2 can be None or not dictionary; treat as empty dictionary
    d2_lookup = d2 if isinstance(d2, dict) else {}
    result = {}
    for key, v1 in d1.items():
        if key not in d2_lookup:
            # key missing in d2; include it
            result[key] = v1
            continue
        v2 = d2_lookup[key]
        # both present
        if isinstance(v1, dict) and isinstance(v2, dict):
            if level == 0:
                # no further recursion; treat as difference
                result[key] = v1
                continue
            sub_level = level - 1 if level > 0 else level
            sub_diff = difference(v1, v2, sub_level)
            if sub_diff:  # non-empty
                result[key] = sub_diff
        else:
            # not both dicts, compare values
            try:
                equal = v1 == v2
            except Exception:
                equal = False
            if not equal:
                result[key] = v1
    return result

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate input
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError('difference expects two dictionaries')

    def _diff(dict1, dict2, cur_level):
        result = {}
        for key, val1 in dict1.items():
            if key not in dict2:
                # Key missing in dict2, include it
                result[key] = val1
            else:
                val2 = dict2[key]
                if val1 == val2:
                    # identical, skip
                    continue
                # Values differ
                if isinstance(val1, dict) and isinstance(val2, dict) and cur_level != 0:
                    # Recurse if depth allows
                    next_level = None if cur_level == -1 else cur_level - 1
                    sub = _diff(val1, val2, next_level)
                    if sub:
                        result[key] = sub
                else:
                    # Non-dict or no recursion depth left; include original value
                    result[key] = val1
        return result

    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    The function does not modify *d1* or *d2*.
    """
    if not isinstance(d1, dict):
        return {}
    if not isinstance(d2, dict):
        # All items in d1 are differences
        return {k: v for k, v in d1.items()}

    diff = {}
    for key, val1 in d1.items():
        if key not in d2:
            # key missing in d2: copy the value from d1
            diff[key] = val1
        else:
            val2 = d2[key]
            # Determine whether to recurse into nested dicts
            if isinstance(val1, dict) and isinstance(val2, dict) and level != 0:
                # Compute next recursion level
                next_level = level if level == -1 else level - 1
                subdiff = difference(val1, val2, next_level)
                if subdiff:
                    diff[key] = subdiff
            elif val1 != val2:
                # values differ: include from d1
                diff[key] = val1
    return diff

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError('Both d1 and d2 must be dictionaries')

    def _diff(a, b, curr_level):
        out = {}
        for key, val in a.items():
            if key not in b:
                # key only in a, include it
                if isinstance(val, dict) and (curr_level > 0 or curr_level == -1):
                    out[key] = _diff(val, {}, curr_level - 1 if curr_level > 0 else curr_level)
                else:
                    out[key] = val
            else:
                b_val = b[key]
                if isinstance(val, dict) and isinstance(b_val, dict):
                    # recurse into nested dicts if depth permits
                    if curr_level > 0 or curr_level == -1:
                        sub = _diff(val, b_val, curr_level - 1 if curr_level > 0 else curr_level)
                        if sub:
                            out[key] = sub
                else:
                    # values differ
                    if val != b_val:
                        out[key] = val
        return out

    return _diff(d1, d2, level)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    coord_arr = np.asarray(coord)
    if coord_arr.ndim != 1 or coord_arr.size != len(self.edges):
        raise ValueError(
            f"coord must be a 1‑D array of length {len(self.edges)}, "
            f"got {coord_arr.shape}"
        )

    indices = []
    for dim, edge in enumerate(self.edges):
        bin_idx = np.searchsorted(edge, coord_arr[dim], side='right') - 1
        # Valid indices are 0 .. len(edge)-2
        if bin_idx < 0 or bin_idx >= (edge.size - 1):
            # Coordinate outside valid range; ignore this point
            return
        indices.append(bin_idx)

    try:
        self.values[tuple(indices)] += weight
    except Exception as exc:
        raise RuntimeError(f"Failed to fill histogram: {exc}") from exc

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re
    # Basic regex for allowed labels: keys must start with a letter and contain
    # letters, digits, or underscores. Adjust as needed.
    _LABEL_REGEX = re.compile(r'^[A-Za-z][A-Za-z0-9_]{0,63}$')
    errors = []

    for key, value in labels.items():
        key_str = str(key)
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({key_str: 'expected string or bytes-like object'})
        else:
            try:
                if not _LABEL_REGEX.search(key):
                    errors.append(
                        {key_str: f"Label key '{key}' does not match the regex { _LABEL_REGEX.pattern }"}
                    )
            except TypeError:
                errors.append({key_str: 'expected string or bytes-like object'})

        # Validate value type
        # For values that are collections (list/tuple/set/dict), we simply treat the
        # collection itself as the value to avoid lengthy recursion.
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): 'expected string or bytes-like object'})
        else:
            try:
                if not _LABEL_REGEX.search(value):
                    errors.append(
                        {str(value): f"Label value '{value}' does not match the regex { _LABEL_REGEX.pattern }"}
                    )
            except TypeError:
                errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    errors = []

    # Helper to validate a single string against a simple regex pattern:
    # Begins with a letter, followed by letters, digits, or underscores.
    def _is_valid_label_component(component):
        if not isinstance(component, (str, bytes)):
            return False
        if not component:
            return False
        if not component[0].isalpha():
            return False
        for ch in component:
            if not (ch.isalnum() or ch == "_"):
                return False
        return True

    for key, value in labels.items():
        # Validate key
        if not _is_valid_label_component(key):
            key_repr = str(key)
            if not isinstance(key, (str, bytes)):
                errors.append({key_repr: "expected string or bytes-like object"})
            else:
                errors.append({key: f"Label key '{key}' does not match the regex [...]"})

        # Validate value
        if not _is_valid_label_component(value):
            value_repr = str(value)
            if not isinstance(value, (str, bytes)):
                errors.append({value_repr: "expected string or bytes-like object"})
            else:
                errors.append({value: f"Label value '{value}' does not match the regex [...]"})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    # Define regex patterns for keys and values
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    value_pattern = key_pattern

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({repr(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex
            try:
                if not key_pattern.match(key):
                    errors.append(
                        {
                            key: (
                                f"Label key '{key}' does not match "
                                f"the regex {key_pattern.pattern}"
                            )
                        }
                    )
            except Exception:
                # In case matching fails, treat as regex mismatch
                errors.append(
                    {
                        key: (
                            f"Label key '{key}' does not match "
                            f"the regex {key_pattern.pattern}"
                        )
                    }
                )

        # Validate value type
        if isinstance(value, (str, bytes)):
            # Validate string value regex
            try:
                if not value_pattern.match(value):
                    errors.append(
                        {
                            key: (
                                f"Label value '{value}' does not match "
                                f"the regex {value_pattern.pattern}"
                            )
                        }
                    )
            except Exception:
                errors.append(
                    {
                        key: (
                            f"Label value '{value}' does not match "
                            f"the regex {value_pattern.pattern}"
                        )
                    }
                )
        else:
            # Non-string value, raise generic type error
            errors.append({repr(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    # Define regex patterns as strings (used only for error messages)
    key_regex = r'^[a-zA-Z_][a-zA-Z0-9_]*$'
    value_regex = r'^[a-zA-Z_][a-zA-Z0-9_]*$'

    def _is_valid_string(s):
        """Return True if s is a non‑empty string and matches the allowed pattern
        (letters, digits, underscore, starting with a letter or underscore)."""
        if not isinstance(s, (str, bytes)):
            return False
        if isinstance(s, bytes):
            try:
                s = s.decode()
            except Exception:
                return False
        if not s:
            return False
        # First character must be a letter or underscore
        if not (s[0].isalpha() or s[0] == '_'):
            return False
        # Remaining characters must be alphanumeric or underscore
        for ch in s:
            if not (ch.isalnum() or ch == '_'):
                return False
        return True

    errors = []

    for key, value in labels.items():
        # Validate key
        if not _is_valid_string(key):
            # Key is either not a string or not matching the pattern
            if not isinstance(key, (str, bytes)):
                errors.append({str(key): 'expected string or bytes-like object'})
            else:
                errors.append({key: f"Label key '{key}' does not match the regex [{key_regex}]"})
        # Validate value
        if not _is_valid_string(value):
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                errors.append({value: f"Label value '{value}' does not match the regex [{value_regex}]"})
    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    result = {}
    for key, value in manifest_dict.items():
        # If the value is a dict, recurse
        if isinstance(value, dict):
            if first_level and key == "metadata":
                # Preserve only the identifying subfields 'name' and 'namespace'
                meta = {}
                if "name" in value:
                    meta["name"] = value["name"]
                if "namespace" in value:
                    meta["namespace"] = value["namespace"]
                result[key] = meta
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
        # If the value is a list, generate a list with the default of the first element
        elif isinstance(value, list):
            if not value:
                result[key] = []
            else:
                first_item = value[0]
                if isinstance(first_item, dict):
                    result[key] = [
                        generate_default_observer_schema_dict(first_item, first_level=False)
                    ]
                else:
                    result[key] = [None]
        # Scalar values: replace with None or copy for top‑level identifying fields
        else:
            if first_level and key in ("apiVersion", "kind"):
                result[key] = value
            else:
                result[key] = None
    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.
    The function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    If ``first_level`` is True the function will copy identifying fields
    ('apiVersion', 'kind' and 'metadata') from the original manifest.

    Arguments
    ----------
    manifest_dict : dict
        Partial Kubernetes resources.
    first_level : bool, optional
        Whether the dictionary represents the whole observer schema of a
        Kubernetes resource.

    Returns
    -------
    dict
        Generated partial observer_schema.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    result = {}
    identifying_keys = {"apiVersion", "kind", "metadata"}

    for key, value in manifest_dict.items():
        # Copy identifying fields at the top level
        if first_level and key in identifying_keys:
            result[key] = value
            continue

        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Preserve list structure but replace non-dict items with None
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                elif isinstance(item, list):
                    # Recursively process nested lists
                    new_list.append(transform_list(item))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            # Non-list/non-dict values are replaced with None
            result[key] = None

    return result


def transform_list(lst):
    """Recursively transform a list, replacing non-dict values with None."""
    new = []
    for el in lst:
        if isinstance(el, dict):
            new.append(generate_default_observer_schema_dict(el, first_level=False))
        elif isinstance(el, list):
            new.append(transform_list(el))
        else:
            new.append(None)
    return new

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Special handling: preserve entire metadata block when at top level
            if first_level and key == "metadata" and isinstance(value, dict):
                # deep copy to keep original values
                result[key] = {k: v for k, v in value.items()}
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # keep list as is; sub-elements will be processed elsewhere if needed
            result[key] = value
        else:
            # scalar value
            if first_level and key in {"apiVersion", "kind"}:
                result[key] = value
            else:
                result[key] = None

    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dictionary")

    # Fields whose values should be kept as-is when first_level is True
    IDENTIFYING_KEYS = {"apiVersion", "kind", "metadata"}

    def _recurse(d, is_first):
        new_obj = {}
        for key, value in d.items():
            if isinstance(value, dict):
                new_obj[key] = _recurse(value, False)
            elif isinstance(value, list):
                new_list = []
                for item in value:
                    if isinstance(item, dict):
                        new_list.append(_recurse(item, False))
                    else:
                        new_list.append(None)
                new_obj[key] = new_list
            else:
                if is_first and key in IDENTIFYING_KEYS:
                    new_obj[key] = value
                else:
                    new_obj[key] = None
        return new_obj

    return _recurse(manifest_dict, first_level)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present

    """
    # Basic sanity checks – the function works with dicts internally.
    if not isinstance(last_applied_manifest, dict):
        raise TypeError(
            "last_applied_manifest must be a dict, got %s" % type(last_applied_manifest)
        )
    if not isinstance(observer_schema, list):
        raise TypeError(
            "observer_schema must be a list, got %s" % type(observer_schema)
        )
    if not isinstance(response, dict):
        raise TypeError(
            "response must be a dict, got %s" % type(response)
        )

    for item in observer_schema:
        # Primitive–scalar field specified by a string key
        if isinstance(item, str):
            key = item
            if key not in last_applied_manifest:
                # Initialise with a copy of the response value if present,
                # otherwise None.
                last_applied_manifest[key] = response.get(key, None)
            continue

        # Nested or complex field – the schema dict is expected to contain
        # a ``name`` key and optionally a ``schema`` key for further nesting.
        if isinstance(item, dict):
            key = item.get("name")
            sub_schema = item.get("schema")

            if key is None:
                continue  # nothing to process

            # Initialise the key if missing
            if key not in last_applied_manifest:
                # Default initial value is the type of the sub‑schema
                if isinstance(sub_schema, list):
                    last_applied_manifest[key] = []
                else:
                    last_applied_manifest[key] = {}

            # If the sub‑schema exists, recurse into the appropriate helper
            # based on the type of the existing value.
            if sub_schema and isinstance(sub_schema, list):
                # The field is a list – recurse into each element
                # Ensure we have a list to recurse into
                if not isinstance(last_applied_manifest[key], list):
                    last_applied_manifest[key] = []
                if key in response:
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[key], sub_schema, response[key]
                    )
            elif sub_schema and isinstance(sub_schema, dict):
                # The field is a dict – recurse with the dict schema
                if not isinstance(last_applied_manifest[key], dict):
                    last_applied_manifest[key] = {}
                if key in response:
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[key], sub_schema, response[key]
                    )
            else:
                # No sub‑schema – simple copy if present
                if key in response:
                    last_applied_manifest[key] = response[key]
        else:
            # Ignore items that are neither strings nor dicts
            continue

    return last_applied_manifest

