def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        # Retrieve the application spec
        spec = getattr(app, "spec", None)
        if spec is None:
            raise AttributeError("Application object does not have a 'spec' attribute")

        # Manifest list contains the Kubernetes resources to observe
        manifest = getattr(spec, "manifest", None)
        if manifest is None:
            raise AttributeError("Spec does not contain a 'manifest' attribute")
        if not isinstance(manifest, list):
            raise TypeError("Spec.manifest should be a list of resource dictionaries")

        # Existing observer schemas (may be None or a dict)
        existing = getattr(spec, "observers", None)
        if existing is None:
            existing = {}
        if not isinstance(existing, dict):
            raise TypeError("Spec.observers should be a dictionary mapping kind to schema")

        # Build default schemas for missing kinds
        for resource in manifest:
            if not isinstance(resource, dict):
                continue
            kind = resource.get("kind")
            if not kind:
                continue
            if kind not in existing:
                # Very minimal default schema: an object with a 'status' property
                default_schema = {"type": "object", "properties": {"status": {"type": "object"}}}
                existing[kind] = default_schema

        # Attach the updated observers back to the spec
        setattr(spec, "observers", existing)
        return existing

    except Exception as exc:
        raise RuntimeError(f"Failed to generate default observer schemas: {exc}") from exc

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate expected structure
    if not hasattr(app, "spec"):
        raise ValueError("The application object does not have a 'spec' attribute.")
    if not hasattr(app.spec, "manifest"):
        raise ValueError("The application spec does not contain a 'manifest' attribute.")
    if not hasattr(app.spec, "observer"):
        # Some applications may not have observers defined; create an empty structure
        app.spec.observer = type("Observer", (), {})()
    # Ensure we can hold schemas
    if not hasattr(app.spec.observer, "schemas"):
        app.spec.observer.schemas = {}
    schemas = app.spec.observer.schemas
    # Iterate through all resources in the manifest
    for resource in app.spec.manifest:
        # Skip non‑dict entries
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            # If the resource does not specify a kind we cannot create a schema
            continue
        if kind in schemas:
            # Custom schema already exists; skip
            continue
        # Build a minimal default schema containing the apiVersion and kind
        default_schema = {
            "kind": kind,
            "apiVersion": resource.get("apiVersion", "v1"),
            "metadata": {"name": "<resource-name>", "namespace": "<namespace>"},
        }
        schemas[kind] = default_schema
    # Return the updated schema mapping for potential further use
    return schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.
    """
    # Import the ObserverSchema class only if available
    ObserverSchema = None
    try:
        from krake.data.schema import schema as ks
        ObserverSchema = ks.ObserverSchema
    except Exception:
        ObserverSchema = None

    # Ensure the application spec has a manifest list
    manifest = getattr(app.spec, "manifest", [])
    if not isinstance(manifest, list):
        manifest = []

    # Ensure the observer_schema list exists
    observers = getattr(app.spec, "observer_schema", None)
    if observers is None or not isinstance(observers, list):
        observers = []
        app.spec.observer_schema = observers

    # Build a set of (kind, name) tuples for which a schema already exists
    existing = set()
    for obs in observers:
        try:
            if isinstance(obs, ObserverSchema):
                res = obs.resource
            else:
                res = obs.get("resource")
            if not res:
                continue
            kind = res.get("kind")
            meta = res.get("metadata", {})
            name = meta.get("name")
            if kind and name:
                existing.add((kind, name))
        except Exception:
            continue

    # Iterate over resources in the manifest and add default schemas for missing ones
    for resource in manifest:
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        metadata = resource.get("metadata", {})
        name = metadata.get("name")
        if not (kind and name):
            continue
        if (kind, name) in existing:
            continue

        # Create a default observer schema
        if ObserverSchema:
            # The ObserverSchema constructor may vary; use kwargs defensively
            try:
                default_obs = ObserverSchema(resource=resource, events=["ADDED", "MODIFIED", "DELETED"])
            except TypeError:
                # Fallback if constructor signature differs
                default_obs = ObserverSchema(resource=resource)
        else:
            # Fallback: simple dict representation
            default_obs = {
                "resource": resource,
                "events": ["ADDED", "MODIFIED", "DELETED"],
            }

        observers.append(default_obs)
    return None

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource identifier (e.g., name) to the default observer schema.
    """
    default_schema = {}
    default_mapping = {}

    # Attempt to access the manifest list; guard against missing attributes
    try:
        manifest = getattr(app, "spec", {}).get("manifest", None)
    except AttributeError:
        manifest = None

    if not manifest or not isinstance(manifest, list):
        return default_mapping

    for resource in manifest:
        if not isinstance(resource, dict):
            continue

        # Determine the identifier for the resource, typically its metadata.name
        res_name = None
        if "metadata" in resource and isinstance(resource["metadata"], dict):
            res_name = resource["metadata"].get("name")
        if not res_name:
            res_name = resource.get("name")

        if not res_name:
            # Skip resources without a recognizable name to avoid ambiguity
            continue

        # Skip resources that already define a custom observer schema
        if "observer_schema" in resource:
            continue

        # Attach the default observer schema
        default_mapping[res_name] = default_schema

    return default_mapping

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application has a spec with the required attributes
    if not hasattr(app, "spec"):
