        # Build a unique key for the resource; use apiVersion/kind if available
        api_version = resource.get("apiVersion", "")
        kind = resource.get("kind", "")
        if not api_version or not kind:
            # Skip resources that don't define these fields
            continue
        key = f"{api_version}/{kind}"

        # If a custom schema already exists for this key, skip
        if key in observer_schema:
