                "annotations": {},
                "finalizers": [],
                "ownerReferences": []
            }
        }

        observer_schema[key] = default_schema

    # Store the updated observer schema back into the app spec
    app.spec.observer_schema = observer_schema
    return observer_schema

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    import json

    try:
        # Determine whether path is a filesystem path or a pyfs root
        if isinstance(path, str):
            # Local filesystem path
            if not os.path.isdir(path):
                return False
            fs = None
            root_path = path
        else:
            # Assume pyfs filesystem root
            fs = path
            root_path = ""

        # Helper to build path relative to root
        def rel(p):
            return os.path.join(root_path, p) if fs is None else p

        # Check existence of .ocfl_version file
        version_path = rel(".ocfl_version")
        if fs:
            if not fs.exists(version_path):
                return False
            try:
                with fs.open(version_path, "r") as f:
                    json.loads(f.read())
            except Exception:
                return False
        else:
            if not os.path.isfile(version_path):
                return False
            try:
                with open(version_path, "r") as f:
                    json.loads(f.read())
            except Exception:
                return False

        # Check objects directory
        objects_dir = rel("objects")
        if fs:
            if not fs.isdir(objects_dir):
                return False
            # At least one object directory must exist
            try:
                subdirs = [
                    d
                    for d in fs.listdir(objects_dir)
                    if fs.isdir(fs.path.join(objects_dir, d))
                ]
            except Exception:
                return False
            if not subdirs:
                return False
        else:
            objects_dir_path = os.path.join(root_path, "objects")
            if not os.path.isdir(objects_dir_path):
                return False
            subdirs = [
                d
                for d in os.listdir(objects_dir_path)
                if os.path.isdir(os.path.join(objects_dir_path, d))
            ]
            if not subdirs:
                return False

        # If all checks pass, the object is considered valid
        return True
    except Exception:
        # Any unexpected error is treated as invalid
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        if not os.path.exists(path):
            return False
        if not os.path.isdir(path):
            return False

        # Basic OCFL object detection: look for a .ocfl_root directory
        root_dir = os.path.join(path, ".ocfl_root")
        if not os.path.isdir(root_dir):
            # If .ocfl_root missing, cannot verify as OCFL object
            return False

        # Ensure there is at least one object directory inside .ocfl_root
        # Exclude the ".ocfl_root" key itself
        child_dirs = [
            d for d in os.listdir(root_dir)
            if os.path.isdir(os.path.join(root_dir, d)) and d != ".ocfl_root"
        ]
        if not child_dirs:
            return False

        # If all checks pass, consider the object valid
        return True
    except Exception:
        # Any unexpected exception results in a validation failure
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    import warnings
    # Handle empty or None paths
    if not path:
        return False

    # If path is a pyfs root (FS object), try to get its root path
    if hasattr(path, 'root_path'):
        try:
            path = path.root_path
        except Exception:
            return False

    # Resolve symbolic links and absolute path
    try:
        path = os.path.abspath(os.path.expanduser(path))
    except Exception:
        return False

    # Check existence and directory
    if not os.path.isdir(path):
        return False

    # OCFL object must contain a .ocfl.version file
    version_file = os.path.join(path, ".ocfl.version")
    if not os.path.isfile(version_file):
        return False

    # Verify versions directory exists
    versions_dir = os.path.join(path, "versions")
    if not os.path.isdir(versions_dir):
        return False

    # At least one version directory should exist
    try:
        entries = [e for e in os.listdir(versions_dir)
                   if os.path.isdir(os.path.join(versions_dir, e))]
    except Exception:
        return False

    if not entries:
        return False

    # Optional: check that each version directory contains a MANIFEST file
