    The input variable prior is also expected to be an InventoryValidator object and both self
    and prior inventories are assumed to have been checked for internal consistency.
    """
    # Make sure the incoming prior is an InventoryValidator of the same type.
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"prior must be an instance of {type(self).__name__}, got {type(prior).__name__}"
        )

    # Ensure the required attributes exist on both objects.
    required_attrs = ("inventory_version", "schema")
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(
                f"Current inventory object missing required attribute '{attr}'."
            )
        if not hasattr(prior, attr):
            raise AttributeError(
                f"Prior inventory object missing required attribute '{attr}'."
            )

    # The prior inventory should represent an older version than the current one.
    if prior.inventory_version >= self.inventory_version:
        raise ValueError(
            f"Prior inventory version ({prior.inventory_version}) must be "
            f"less than current inventory version ({self.inventory_version})."
        )

    # If both inventories expose a 'entries' (or similar) attribute, ensure that all
    # entries present in the prior exist in the current inventory.
    entries_attr = "entries"
    if hasattr(self, entries_attr) and hasattr(prior, entries_attr):
        current_entries = set(self.entries)
        prior_entries = set(prior.entries)
        missing_entries = prior_entries - current_entries
        if missing_entries:
            raise ValueError(
                f"The following entries are present in the prior inventory but missing in the current inventory: "
                f"{sorted(missing_entries)}"
            )

    # All checks passed – the prior is considered a valid prior version.
    return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an {type(self).__name__} instance, got {type(prior).__name__}")

    # Species and parameters must match
    if set(self.species) != set(prior.species):
        raise ValueError(
            f"Species mismatch between current and prior inventory.\n"
            f"Current: {self.species}\nPrior:   {prior.species}"
        )

    if set(self.parameters) != set(prior.parameters):
        raise ValueError(
            f"Parameter mismatch between current and prior inventory.\n"
            f"Current: {self.parameters}\nPrior:   {prior.parameters}"
        )

    # Stoichiometry matrix shape consistency
    if hasattr(self, "stoichiometry_matrix") and hasattr(prior, "stoichiometry_matrix"):
        if self.stoichiometry_matrix.shape != prior.stoichiometry_matrix.shape:
            raise ValueError(
                f"Stoichiometry matrix shape mismatch.\n"
                f"Current: {self.stoichiometry_matrix.shape}\nPrior:   {prior.stoichiometry_matrix.shape}"
            )

    # Propensities matrix shape consistency
    if hasattr(self, "propensities") and hasattr(prior, "propensities"):
        if self.propensities.shape != prior.propensities.shape:
            raise ValueError(
                f"Propensities shape mismatch.\n"
                f"Current: {self.propensities.shape}\nPrior:   {prior.propensities.shape}"
            )

    # If all checks pass, the prior is considered a valid prior version
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    def _parse_version(v):
        """Parse a version string into a tuple suitable for comparison."""
        parts = str(v).split(".")
        parsed = []
        for part in parts:
            try:
                parsed.append(int(part))
            except ValueError:
                # If part is not purely numeric, keep it as string
                parsed.append(part)
        return tuple(parsed)

    target = _parse_version(version)
    result = {}

    for logical_path, entries in inventory.items():
        file_set = set()
        for entry in entries:
            try:
                if isinstance(entry, dict):
                    ver = entry.get("version")
                    path = entry.get("content_file") or entry.get("path")
                elif isinstance(entry, (list, tuple)) and len(entry) >= 2:
                    ver, path = entry[0], entry[1]
                else:
                    continue
                if ver is None or path is None:
                    continue
                entry_ver = _parse_version(ver)
                if entry_ver >= target:
                    file_set.add(path)
            except Exception:
                # Skip malformed entries silently
                continue
        if file_set:
            result[logical_path] = file_set
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    def _compare_versions(v1, v2):
        """Return 1 if v1>v2, -1 if v1<v2, 0 if equal."""
        import re

        def _parse(v):
            parts = re.split(r"[.-]", str(v))
            parsed = []
            for p in parts:
                if p.isdigit():
                    parsed.append(int(p))
                else:
                    parsed.append(p)
            return parsed

        p1, p2 = _parse(v1), _parse(v2)
        # List comparison in python is lexicographical
        if p1 > p2:
            return 1
        if p1 < p2:
            return -1
        return 0

    log_to_files = {}

    if isinstance(inventory, dict):
        for logical_path, ver_map in inventory.items():
            if isinstance(ver_map, dict):
                # mapping of version -> file
                for ver, file_path in ver_map.items():
                    try:
                        if _compare_versions(ver, version) >= 0:
                            log_to_files.setdefault(logical_path, set()).add(file_path)
                    except Exception:
                        continue
            elif isinstance(ver_map, list):
                for item in ver_map:
                    if isinstance(item, (list, tuple)) and len(item) == 2:
                        ver, file_path = item
                        try:
                            if _compare_versions(ver, version) >= 0:
                                log_to_files.setdefault(logical_path, set()).add(file_path)
                        except Exception:
                            continue
            else:
                # Unsupported inner structure; skip
                continue
    elif isinstance(inventory, (list, tuple)):
        for entry in inventory:
            if isinstance(entry, dict):
                # Common field names: logical_path, version, content_file
                logical_path = entry.get("logical_path") or entry.get("logicalPath") or entry.get("path")
                file_path = entry.get("content_file") or entry.get("file") or entry.get("content")
                ver = entry.get("version")
            elif isinstance(entry, (list, tuple)) and len(entry) >= 3:
                logical_path, ver, file_path = entry[:3]
            else:
                continue

            if logical_path and ver is not None and file_path:
                try:
                    if _compare_versions(ver, version) >= 0:
                        log_to_files.setdefault(logical_path, set()).add(file_path)
                except Exception:
                    continue
    else:
        raise TypeError("Unsupported inventory type: expected dict or list")

    return log_to_files

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    from collections import defaultdict

    if inventory is None:
        raise ValueError("inventory cannot be None")

    result = defaultdict(set)

    # Helper to extract key attributes from an entry
    def _get_path(entry):
        return entry.get("logical_path") or entry.get("path")

    def _get_version(entry):
        return entry.get("version")

    def _get_file(entry):
        return entry.get("content_file") or entry.get("file")

    # Determine iterable over entries (handle list, tuple, or dict of entries)
    if isinstance(inventory, dict):
        entries = inventory.values()
    else:
        entries = inventory

    # First, collect all entries that match the requested version
    for entry in entries:
        try:
            lv = _get_path(entry)
            if lv is None:
                continue
            v = _get_version(entry)
            if v is None:
                continue
            if v == version:
                f = _get_file(entry)
                if f:
                    result[lv].add(f)
        except Exception:
            # Skip malformed entries
            continue

    # Then add references to duplicate files from later versions
    for entry in entries:
        try:
            lv = _get_path(entry)
            if lv is None:
                continue
            v = _get_version(entry)
            if v is None:
                continue
            # Attempt simple comparison; if it fails, skip this entry
            try:
                if v > version:
                    if lv in result:
                        f = _get_file(entry)
                        if f:
                            result[lv].add(f)
            except Exception:
                continue
        except Exception:
            continue

    return dict(result)

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Helper function to compare versions (string comparison if possible)
    def _version_le(v1, v2):
        try:
            return str(v1) <= str(v2)
        except Exception:
            return False

    if inventory is None:
        raise ValueError("Inventory cannot be None")
    mapping = {}
    # Support inventory as dict or list
    try:
        # If inventory is a dict with logical_path as keys
        if isinstance(inventory, dict):
            for logical_path, data in inventory.items():
                files = set()
                # data may be dict mapping version -> content file(s)
                if isinstance(data, dict):
                    for ver, content in data.items():
                        if ver is None:
                            continue
                        if _version_le(ver, version):
                            if isinstance(content, (list, tuple, set)):
                                files.update(content)
                            else:
                                files.add(content)
                # data may be list of dicts or values
                elif isinstance(data, (list, tuple)):
                    for item in data:
                        try:
                            ver = item.get("version")
                        except AttributeError:
                            ver = None
                        if ver is None:
                            continue
                        if _version_le(ver, version):
                            try:
                                content = item.get("content_file") or item.get("content")
                                if isinstance(content, (list, tuple, set)):
                                    files.update(content)
                                else:
                                    files.add(content)
                            except Exception:
                                pass
                # otherwise treat data directly as content
                else:
                    if _version_le(data, version):
                        files.add(data)
                mapping[logical_path] = files
        # If inventory is a list of entries
        elif isinstance(inventory, (list, tuple)):
            for entry in inventory:
                if not isinstance(entry, dict):
                    continue
                logical_path = entry.get("logical_path") or entry.get("logical_path_in_state")
                if logical_path is None:
                    continue
                ver = entry.get("version")
                if ver is None or not _version_le(ver, version):
                    continue
                content = entry.get("content_file") or entry.get("content") or entry.get("file")
                if content is None:
                    continue
                mapping.setdefault(logical_path, set()).add(content)
        else:
            raise TypeError("Unsupported inventory type")
    except Exception as exc:
        raise ValueError(f"Failed to process inventory: {exc}") from exc

    return mapping

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure that fixity is a dictionary mapping file names to hashes
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary of file names to hashes")

    # Ensure manifest_files is iterable, turn into a set for fast lookup
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise ValueError("manifest_files must be an iterable of file names")

    # Find any file names referenced in fixity that are not in the manifest
    invalid_refs = set(fixity) - manifest_set
    if invalid_refs:
        raise ValueError(
            f"Fixity block references unknown files: {', '.join(sorted(invalid_refs))}"
        )

    # Validate each hash value: must be a non-empty string of hex digits
    for fname, hash_val in fixity.items():
        if not isinstance(hash_val, str) or not hash_val:
            raise ValueError(
                f"Hash for file '{fname}' must be a non-empty string"
            )
        # Simple hex digit check – allows both upper and lower case
        if not all(c in "0123456789abcdefABCDEF" for c in hash_val):
            raise ValueError(
                f"Hash for file '{fname}' contains non-hexadecimal characters: {hash_val}"
            )

    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Basic type checks
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")
        if not isinstance(manifest_files, (list, set, tuple)):
            raise ValueError("manifest_files must be a list, set, or tuple")

        manifest_set = set(manifest_files)

        # Required keys in the fixity dictionary
        required_keys = {"hash", "files"}
        missing = required_keys.difference(fixity.keys())
        if missing:
            raise ValueError(f"Missing required fixity keys: {', '.join(sorted(missing))}")

        # Validate hash value
        if not isinstance(fixity["hash"], str):
            raise ValueError("The 'hash' value must be a string")

        # Validate files list
        files = fixity["files"]
        if not isinstance(files, list):
            raise ValueError("The 'files' entry must be a list")
        for f in files:
            if not isinstance(f, str):
                raise ValueError(f"File reference {f!r} in fixity is not a string")
            if f not in manifest_set:
                raise ValueError(f"Fixity references unknown file: {f!r}")

        return True

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Helper for error raising
    def _error(msg):
        raise ValueError(msg)

    if not isinstance(fixity, dict):
        _error("Fixity block must be a dictionary")

    if 'files' not in fixity:
        _error("Fixity block missing 'files' key")

    files_section = fixity['files']
    if not isinstance(files_section, dict):
        _error("'files' entry must be a dictionary mapping file paths to checksums")

    # Normalise manifest file collection for efficient membership checks
    manifest_set = set(manifest_files)

    valid_algorithms = {
        'md5', 'sha1', 'sha256', 'sha384', 'sha512'
    }

    for file_path, checksum_info in files_section.items():
        if file_path not in manifest_set:
            _error(f"Fixity references file not present in manifest: {file_path}")

        if not isinstance(checksum_info, dict):
            _error(f"Checksum entry for '{file_path}' must be a dictionary")

        if not checksum_info:
            _error(f"Checksum entry for '{file_path}' is empty")

        # Ensure at least one known algorithm is present
        if not any(alg in valid_algorithms for alg in checksum_info):
            _error(
                f"Checksum entry for '{file_path}' must contain at least one "
                f"known algorithm: {', '.join(sorted(valid_algorithms))}"
            )

        for alg, value in checksum_info.items():
            if alg not in valid_algorithms:
                _error(
                    f"Unsupported algorithm '{alg}' in checksum entry for "
                    f"'{file_path}'. Supported algorithms are: "
                    f"{', '.join(sorted(valid_algorithms))}"
                )
            if not isinstance(value, str) or not value.strip():
                _error(
                    f"Checksum value for algorithm '{alg}' in '{file_path}' must be a non-empty string"
                )

    # No return value needed; success indicated by absence of exception
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError(f"Fixity block must be a dict, got {type(fixity).__name__}")

    # Ensure manifest_files is an iterable of strings
    if not hasattr(manifest_files, "__iter__"):
        raise ValueError(f"Manifest files must be an iterable, got {type(manifest_files).__name__}")
    manifest_set = set()
    for entry in manifest_files:
        if not isinstance(entry, str):
            raise ValueError("All manifest file names must be strings")
        manifest_set.add(entry)

    # Validate each entry in the fixity block
    for file_name, info in fixity.items():
        if file_name not in manifest_set:
            raise ValueError(f"Fixity entry '{file_name}' not present in the manifest")
        if not isinstance(info, dict):
            raise ValueError(f"Fixity info for '{file_name}' must be a dict, got {type(info).__name__}")

        # Expect 'algorithm' and 'checksum' keys
        for key in ("algorithm", "checksum"):
            if key not in info:
                raise ValueError(f"Fixity info for '{file_name}' missing required key '{key}'")
            if not isinstance(info[key], str) or not info[key]:
                raise ValueError(f"Fixity info for '{file_name}' key '{key}' must be a non-empty string")

    # If we get here, the fixity block is considered valid
    return None

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure the arguments are of the expected type
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dict")
    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("manifest_files must be a list, tuple, or set")
    manifest_set = set(manifest_files)

    # Each key in the fixity block should correspond to a file in the manifest
    for file_path, metadata in fixity.items():
        if file_path not in manifest_set:
            raise ValueError(f"Fixity references unknown file: {file_path}")

        # Expect the metadata for each file to include an algorithm and the checksum
        if not isinstance(metadata, dict):
            raise ValueError(
                f"Metadata for file '{file_path}' must be a dict"
            )
        if 'algorithm' not in metadata or 'checksum' not in metadata:
            raise ValueError(
                f"Metadata for file '{file_path}' must contain 'algorithm' and 'checksum' keys"
            )
        if not isinstance(metadata['algorithm'], str):
            raise ValueError(
                f"Algorithm for file '{file_path}' must be a string"
            )
        if not isinstance(metadata['checksum'], (str, bytes)):
            raise ValueError(
                f"Checksum for file '{file_path}' must be a string or bytes"
            )

    # Ensure no files are missing in the fixity block that are present in the manifest
    missing = manifest_set - set(fixity.keys())
    if missing:
        raise ValueError(
            f"Fixity block does not contain entries for the following files: {', '.join(sorted(missing))}"
        )
    return True

def files_list(path):
    """Return the files in `path`"""
    # If path does not exist, raise FileNotFoundError
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")

    # If it's a file, return it as a list
    if os.path.isfile(path):
        return [os.path.abspath(path)]

    # If it's a directory, list all files inside (non-recursively)
    if os.path.isdir(path):
        try:
            return [
                os.path.abspath(os.path.join(path, f))
                for f in os.listdir(path)
                if os.path.isfile(os.path.join(path, f))
            ]
        except OSError:
            # If something goes wrong accessing the directory, return an empty list
            return []

    # For any other type, return an empty list
    return []

