def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
        Mapping of package base names (derived from XML filenames) to lists of
        relative file names that share that base name.
    """
    import os
    result = {}
    try:
        if not os.path.isdir(folder):
            raise ValueError(f"Provided path is not a directory: {folder}")

        # Build temporary mapping from basename to list of files
        temp = {}
        for entry in os.listdir(folder):
            path = os.path.join(folder, entry)
            if not os.path.isfile(path):
                continue
            base, ext = os.path.splitext(entry)
            temp.setdefault(base, []).append(entry)

        # Keep only groups that contain an .xml file
        for base, files in temp.items():
            xml_file = None
            for f in files:
                if f.lower().endswith(".xml"):
                    xml_file = f
                    break
            if xml_file:
                result[base] = files

    except Exception as exc:
        # Log the exception or handle as needed; re-raise for visibility
        raise RuntimeError(f"Unable to explore folder '{folder}': {exc}") from exc

    return result

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Validate language argument
    if not isinstance(lang, str) or not lang:
        raise ValueError("lang must be a non-empty string")

    # Validate file_path argument
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string")
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File '{file_path}' does not exist")

    # Infer the original filename by stripping the language suffix
    base_name = os.path.basename(file_path)
    name_part, ext = os.path.splitext(base_name)
    if name_part.endswith(f"-{lang}"):
        original_name = name_part[:-(len(lang) + 1)] + ext
    else:
        original_name = base_name

    # Ensure the container exists
    if not hasattr(self, "renditions") or not isinstance(self.renditions, dict):
        self.renditions = {}

    # Create or update the mapping for the original file
    if original_name not in self.renditions:
        self.renditions[original_name] = {}
    self.renditions[original_name][lang] = file_path

    return self.renditions[original_name]

def add_rendition(self, lang, file_path):
    """Add a rendition file for the specified language.

    Args:
        lang: Language code or ``"original"`` for the base file.
        file_path: Path to the rendition file.

    Returns:
        bool: ``True`` if the rendition was added successfully,
        ``False`` otherwise.
    """
    try:
        # Basic validation
        if not isinstance(lang, str) or not lang:
            raise ValueError("Language code must be a non‑empty string.")

        # Validate file path
        if not isinstance(file_path, str):
            raise TypeError("file_path must be a string.")
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")

        # Ensure renditions dict exists
        if not hasattr(self, "_renditions") or not isinstance(self._renditions, dict):
            self._renditions = {}

        # Store the rendition
        self._renditions[lang] = file_path
        return True

    except Exception:
        # Log the error if a logger is available, otherwise ignore
        try:
            logger = getattr(self, "_logger", None)
            if logger:
                logger.exception("Failed to add rendition: %s" % lang)
        except Exception:
            pass
        return False

def add_asset(self, basename, file_path):
    """
    {
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """

    import os

    # Ensure the provided path is a directory
    if not os.path.isdir(file_path):
        raise ValueError(f"Provided file_path '{file_path}' is not a directory")

    assets = {}
    for entry in os.listdir(file_path):
        if entry.startswith(basename):
            full_path = os.path.join(file_path, entry)
            if os.path.isfile(full_path):
                assets[entry] = full_path

    if not assets:
        raise FileNotFoundError(f"No assets found starting with basename '{basename}' in '{file_path}'")

    return assets

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    try:
        # Open the zip file for reading
        with zipfile.ZipFile(zip_path, "r") as zf:
            # Gather all entry names and their raw contents
            contents = {info.filename: zf.read(info) for info in zf.infolist()}

            # Identify XML files and group related files by the XML basename
            for xml_name in filter(lambda n: n.lower().endswith(".xml"), contents):
                base = os.path.splitext(os.path.basename(xml_name))[0]
                if base not in result:
                    result[base] = {}

                # Add all files that share the same basename (including the XML file)
                for fname, data in contents.items():
                    if os.path.splitext(os.path.basename(fname))[0] == base:
                        result[base][fname] = data
    except (FileNotFoundError, zipfile.BadZipFile, Exception):
        # If the file cannot be read or is not a valid ZIP, return an empty dict
        return {}
    return result

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        A dictionary mapping each XML base name to a sub‑dictionary of
        file names (full paths in the archive) and their corresponding
        binary contents. Only packages that contain an XML file are
        returned; all files that share the same base name as that XML
        are grouped together.
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")

    try:
        with zipfile.ZipFile(zip_path, "r") as z:
            # First collect all base names of XML files in the archive
            xml_basenames = set()
            for info in z.infolist():
                if info.is_dir():
                    continue
                if info.filename.lower().endswith(".xml"):
                    base = os.path.splitext(os.path.basename(info.filename))[0]
                    xml_basenames.add(base)

            # Now gather the files that belong to each XML base
            packages = {}
            for info in z.infolist():
                if info.is_dir():
                    continue
                base = os.path.splitext(os.path.basename(info.filename))[0]
                if base in xml_basenames:
                    if base not in packages:
                        packages[base] = {}
                    content = z.read(info.filename)
                    packages[base][info.filename] = content

            return packages
    except FileNotFoundError:
        raise FileNotFoundError(f"Zip file not found: {zip_path}")
    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Bad zip file: {zip_path}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to explore zip file {zip_path}") from exc

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            for info in z.infolist():
                # Skip directories
                if info.is_dir():
                    continue
                try:
                    content = z.read(info.filename)
                except Exception:
                    # Skip files that can't be read
                    continue
                # Determine the base name (without extension)
                base_name = os.path.splitext(os.path.basename(info.filename))[0]
                if base_name not in packages:
                    packages[base_name] = {}
                packages[base_name][info.filename] = content
    except Exception:
        # If the zip file can't be opened or read, return empty dict
        return {}

    return packages

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os
    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First map directories that contain an XML to its basename
            dir_to_base = {}
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                if name.lower().endswith('.xml'):
                    dirpath = os.path.dirname(name)
                    base = os.path.splitext(os.path.basename(name))[0]
                    dir_to_base[dirpath] = base
                    if base not in packages:
                        packages[base] = {}

            # Now collect all files under each directory that was mapped
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                dirpath = os.path.dirname(name)
                base = dir_to_base.get(dirpath)
                if base is None:
                    continue
                try:
                    data = zf.read(info)
                except Exception:
                    # Skip problematic files
                    continue
                packages[base][name] = data
    except FileNotFoundError:
        raise
    except zipfile.BadZipFile:
        raise
    return packages

def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path` as a list of paths within the zip archive."""
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            # Filter out directory entries (names ending with '/')
            files = [name for name in zf.namelist() if not name.endswith("/") and not name.endswith(".pyc")]
            return files
    except (FileNotFoundError, zipfile.BadZipFile):
        # Return an empty list if the zip file can't be read
        return []

