    """
    import pprint
    try:
        return pprint.pformat(self, indent=indent, width=80, depth=None, compact=not debug)
    except Exception:
        return repr(self)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """

    def _format(obj, level, seen):
        # Handle recursive references
        obj_id = id(obj)
        if obj_id in seen:
            return f'{indent_str * level}<Recursion detected>'

        seen.add(obj_id)

        # Basic types
        if obj is None or isinstance(obj, (bool, int, float)):
            return f'{indent_str * level}{repr(obj)}'
        if isinstance(obj, str):
            return f'{indent_str * level}{repr(obj)}'
        if isinstance(obj, bytes):
            return f'{indent_str * level}bytes({len(obj)} bytes)'

        # Containers
        if isinstance(obj, (list, tuple, set, frozenset)):
            opening = '[' if isinstance(obj, list) else '({' if isinstance(obj, dict) else '{'
            closing = ']' if isinstance(obj, list) else '})'
            lines = [f'{indent_str * level}{opening}']
            for i, item in enumerate(obj):
                lines.append(_format(item, level + 1, seen))
            lines.append(f'{indent_str * level}{closing}')
            return '\n'.join(lines)

        if isinstance(obj, dict):
            lines = [f'{indent_str * level}{{']
            for k, v in obj.items():
                lines.append(f'{indent_str * (level + 1)}{repr(k)}: {_format(v, level + 1, seen)}')
            lines.append(f'{indent_str * level}}}')
            return '\n'.join(lines)

        # Objects with __dict__
        if hasattr(obj, '__dict__'):
            lines = [f'{indent_str * level}{type(obj).__name__} (id={obj_id:#x}) {']
            for attr, val in vars(obj).items():
                lines.append(f'{indent_str * (level + 1)}{attr} = {_format(val, level + 1, seen)}')
            lines.append(f'{indent_str * level}}}')
            return '\n'.join(lines)

        # Fallback to repr
        return f'{indent_str * level}{repr(obj)}'

    # Prepare indentation string
    indent_str = ' ' * indent
    # Start formatting
    try:
        return _format(self, 0, set())
    except Exception as e:
        # In case something goes wrong, return simple representation
        return f'{indent_str}<Error pretty printing: {e}>'

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    visited = set()

    def _repr(obj, level):
        """Recursive helper that returns a pretty representation of *obj*."""
        # Detect recursion
        obj_id = id(obj)
        if obj_id in visited:
            return '...'
        visited.add(obj_id)

        # Terminal types
        if obj is None or isinstance(obj, (bool, int, float, complex, str)):
            return repr(obj)

        # Basic collections
        if isinstance(obj, dict):
            lines = []
            prefix = ' ' * (indent * level)
            for k, v in obj.items():
                line = f'{prefix}{repr(k)}: {_repr(v, level + 1)}'
                lines.append(line)
            return '{\n' + ',\n'.join(lines) + f'\n{" " * (indent * level)}}}'

        if isinstance(obj, (list, tuple, set, frozenset)):
            bracket_start = '[' if isinstance(obj, list) else '(' if isinstance(obj, tuple) else '{'
            bracket_end = ']' if isinstance(obj, list) else ')' if isinstance(obj, tuple) else '}'
            lines = []
            prefix = ' ' * (indent * level)
            for item in obj:
                line = f'{prefix}{_repr(item, level + 1)}'
                lines.append(line)
            return f'{bracket_start}\n' + ',\n'.join(lines) + f'\n{" " * (indent * level)}{bracket_end}'

        # For custom objects: try to pretty print __dict__
        if hasattr(obj, '__dict__'):
            cls_name = obj.__class__.__name__
            label = f'{cls_name}'
            if debug:
                label += f'@{id(obj):#x}'
            lines = [f'{label} {{']
            prefix = ' ' * (indent * (level + 1))
            for attr, value in sorted(obj.__dict__.items()):
                line = f'{prefix}{repr(attr)}: {_repr(value, level + 2)}'
                lines.append(line)
            lines.append(' ' * (indent * level) + '}')
            return '\n'.join(lines)

        # Fallback: use repr
        return repr(obj)

    try:
        return _repr(self, 0)
    except Exception as e:  # pragma: no cover
        # In case of unexpected errors, fall back to default repr
        return f'<Error pretty printing: {e}>'

def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.
    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).
    :param dt: A timezone-aware :class:`datetime.datetime` object.
    """
    if dt.tzinfo is None:
        raise TypeError("_fromutc requires a timezone‑aware datetime")

    # Ensure dt is in UTC so we can compute local time reliably
    if dt.tzinfo.utcoffset(dt) is not None and dt.tzinfo.utcoffset(dt).total_seconds() != 0:
        dt = dt.astimezone(tzutc())

    # Work with the naive representation of the time
    naive = dt.replace(tzinfo=None)

    # Try both fold options to see if they give the same offset
    try:
        naive_fold0 = naive.replace(fold=0)
    except AttributeError:
        naive_fold0 = naive
    try:
        naive_fold1 = naive.replace(fold=1)
    except AttributeError:
        naive_fold1 = naive

    try:
        offset0 = self.utcoffset(naive_fold0)
    except Exception:
        offset0 = None
    try:
        offset1 = self.utcoffset(naive_fold1)
    except Exception:
        offset1 = None

    # If offsets are identical, this time is not ambiguous
    if offset0 == offset1:
        return naive.replace(tzinfo=self)

    # Ambiguous case: decide which fold matches the original UTC time
    cand0 = naive_fold0.replace(tzinfo=self)
    cand1 = naive_fold1.replace(tzinfo=self)
    try:
        if cand0.astimezone(tzutc()) == dt:
            return cand0
    except Exception:
        pass
    return cand1

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        import sys
        try:
            result = namefunc(*args, **kwargs)
        except Exception as exc:
            # Preserve original traceback for caller
            raise
        if sys.version_info[0] < 3:
            # In Python 2, encode unicode to bytestring
            if isinstance(result, unicode):
                return result.encode('utf-8')
            # If already bytes, return as is
            return result
        # In Python 3, return result unchanged
        return result
    return inner_func

