def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    try:
        # Prefer importlib.metadata on Python 3.8+
        import importlib.metadata as importlib_metadata
        try:
            return importlib_metadata.version(__name__)
        except Exception:
            return default
    except ImportError:
        # Fallback to pkg_resources if available
        try:
            import pkg_resources
            try:
                return pkg_resources.get_distribution(__name__).version
            except Exception:
                return default
        except ImportError:
            return default

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"

    # First try to use importlib.metadata (Python 3.8+)
    try:
        from importlib.metadata import version, PackageNotFoundError
        pkg_name = __package__ or __name__.split('.')[0]
        return version(pkg_name)
    except Exception:
        pass

    # Next try to read a local version.py module
    try:
        import importlib.util
        spec = importlib.util.find_spec("version")
        if spec and spec.origin:
            with open(spec.origin, "r") as f:
                for line in f:
                    if line.strip().startswith("__version__"):
                        _, val = line.split("=", 1)
                        return val.strip().strip("'\"")
    except Exception:
        pass

    # Finally, try to read a plain VERSION file in the working directory
    try:
        with open("VERSION", "r") as f:
            return f.read().strip()
    except Exception:
        pass

    return default

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Python 3.8+
        from importlib.metadata import distributions
        try:
            return {dist.metadata["Name"]: dist.version for dist in distributions()}
        except Exception:
            pass
    except ImportError:
        pass

    try:
        import pkg_resources
        return {dist.project_name: dist.version for dist in pkg_resources.working_set}
    except Exception:
        # Fallback: no version information available
        return {"unknown": "unknown"}

