def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            tuple(num_objects, good_objects) - number of objects checked and number of objects that passed validation.
        """
        # Determine the root of the hierarchy.  The method supports a few common patterns
        # (e.g., a `root` attribute, a `hierarchy_root` attribute, or a `objects` property that
        # contains the root elements).  If none of these exist, a clear exception is raised.
        root = None
        for name in ('root', 'hierarchy_root', 'objects'):
            if hasattr(self, name):
                root = getattr(self, name)
                break
        if root is None:
            raise AttributeError(
                "The instance does not expose a root or objects attribute required for hierarchy validation."
            )

        # Internal generator that recursively yields every object in the hierarchy.
        def _traverse(node):
            """Yield a node and all of its descendants.  This works for both object hierarchies
            (where children are available through a `children` attribute or a `sub_objects`
            list) and for simple dictionaries/lists.
            """
            yield node
            # Try common child access patterns
            children = None
            if isinstance(node, dict):
                children = node.get('children', node.get('sub_objects'))
            else:
                children = getattr(node, 'children', None) or getattr(node, 'sub_objects', None)
            if children is None:
                return
            if isinstance(children, (list, tuple)):
                for child in children:
                    yield from _traverse(child)
            elif isinstance(children, dict):
                for child in children.values():
                    yield from _traverse(child)
            # Anything else is treated as a leaf and ignored.

        num_objects = 0
        good_objects = 0

        # Helper functions that user supplied; if not defined this method by default is a no-op
        def _validate_object(node):
            if hasattr(self, '_validate_object'):
                return self._validate_object(node)
            # Default behaviour: if node is a dict, require a 'valid' key that is True
            if isinstance(node, dict) and 'valid' in node:
                if not node['valid']:
                    raise ValueError("Node marked as invalid")
            return True

        def _check_digest(node):
            if hasattr(self, '_check_digest'):
                return self._check_digest(node)
            # Default behaviour: if node has a digest and a data field,
            # check that digest matches data content using a simple sum.
            if isinstance(node, dict) and 'digest' in node and 'data' in node:
                if sum(bytearray(node['data'])) % 256 != node['digest']:
                    raise ValueError("Digest mismatch")
            return True

        try:
            for node in _traverse(root):
                num_objects += 1
                valid = True
                if validate_objects:
                    try:
                        _validate_object(node)
                    except Exception as e:
                        valid = False
                        if show_warnings:
                            print(f"[VALIDATION] Object {node} failed validation: {e}", flush=True)
                if check_digests:
                    try:
                        _check_digest(node)
                    except Exception as e:
                        valid = False
                        if show_warnings:
                            print(f"[DIGEST] Object {node} digest check failed: {e}", flush=True)
                if valid:
                    good_objects += 1
        except Exception as ex:
            # Catch unexpected errors in traversal itself; report and continue
            if show_warnings:
                print(f"[ERROR] Unexpected error during hierarchy traversal: {ex}", flush=True)

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Parameter validation
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a bool")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a bool")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a bool")

    # Attempt to locate the object collection that represents the hierarchy.
    # This is a best‑effort fallback; implementers should adjust according to their data layout.
    try:
        root_objs = getattr(self, "storage_root", None)
        if root_objs is None:
            # Try alternative common names
            root_objs = getattr(self, "root_objects", None)
        if root_objs is None:
            raise AttributeError("No storage_root (or equivalent) attribute found on this instance")
    except Exception as exc:
        raise AttributeError(f"Unable to access storage root: {exc}")

    # Ensure we have an iterable
    if isinstance(root_objs, dict):
        objects_iter = iter(root_objs.values())
    else:
        objects_iter = iter(root_objs)

    num_objects = 0
    good_objects = 0
    warnings = []

    # Helper: compute digest if possible
    def _compute_digest(obj):
        """Compute a SHA256 digest of the given object."""
        import json, hashlib
        try:
            if isinstance(obj, dict):
                data = json.dumps(obj, sort_keys=True)
            else:
                # fall back to object's __dict__
                data = json.dumps(obj.__dict__, sort_keys=True)
        except Exception:
            # If serialization fails, return None
            return None
        return hashlib.sha256(data.encode("utf-8")).hexdigest()

    for obj in objects_iter:
        num_objects += 1
        obj_id = getattr(obj, "id", getattr(obj, "uuid", None))
        # Normal validation
        is_valid = True
        if validate_objects:
            try:
                if hasattr(obj, "validate"):
                    # assume validate raises on failure
                    obj.validate()
                elif isinstance(obj, dict):
                    # minimal generic validation: require key 'id'
                    if "id" not in obj:
                        raise ValueError("Missing required key 'id'")
                else:
                    # use a generic truthiness check
                    pass
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    warnings.append(f"Object {obj_id} failed validation: {exc}")
        # Digest check
        if is_valid and check_digests:
            try:
                expected = getattr(obj, "checksum", None)
                if expected is not None:
                    actual = _compute_digest(obj)
                    if actual is None:
                        raise RuntimeError("Could not compute digest")
                    if actual != expected:
                        is_valid = False
                        if show_warnings:
                            warnings.append(f"Object {obj_id} checksum mismatch (expected {expected}, got {actual})")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    warnings.append(f"Object {obj_id} digest check error: {exc}")

        if is_valid:
            good_objects += 1

    # Emit warnings if requested
    if show_warnings and warnings:
        for w in warnings:
            # In a real implementation, use the logging module
            print("WARNING:", w)

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
