                                m.update(chunk)
                        actual_digest = m.hexdigest()
                        if actual_digest != expected_digest:
                            valid = False
                            if show_warnings:
                                print(f"Digest mismatch for {file_path}: expected {expected_digest}, got {actual_digest}")
                    except Exception as exc:
                        valid = False
                        if show_warnings:
                            print(f"Digest check failed for {file_path}: {exc}")

