        if validate_objects:
            if 'data' not in obj:
                is_valid = False
                if show_warnings:
                    print(f"Object {obj.get('id')} missing mandatory 'data' field.")
            elif obj.get('data') is None:
                is_valid = False
                if show_warnings:
                    print(f"Object {obj.get('id')} has 'data' set to None.")

        # Digest checking
        if check_digests:
            digest_expected = obj.get('digest')
            data = obj.get('data')
            if data is None:
                is_valid = False
                if show_warnings:
                    print(f"Object {obj.get('id')} has no 'data' to compute digest for.")
            else:
                try:
                    import hashlib
                    digest_actual = hashlib.sha256(data.encode('utf-8')).hexdigest()
                    if digest_expected is None:
                        if show_warnings:
                            print(f"Object {obj.get('id')} missing expected digest.")
                        is_valid = False
                    elif digest_actual != digest_expected:
                        if show_warnings:
                            print(f"Digest mismatch for object {obj.get('id')}. "
                                  f"Expected {digest_expected}, got {digest_actual}.")
                        is_valid = False
                except Exception as exc:
                    if show_warnings:
                        print(f"Error computing digest for object {obj.get('id')}: {exc}")
                    is_valid = False

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Try to get an iterable of (id, obj) pairs from the instance.
    try:
        if hasattr(self, 'objects') and isinstance(self.objects, (list, tuple)):
            iterable = self.objects
        elif hasattr(self, 'storage'):
            iterable = getattr(self.storage, 'items', lambda: [])()
        else:
            iterable = []
    except Exception:
        iterable = []

    for entry in iterable:
        try:
            # Normalize entry to (id, obj)
            if isinstance(entry, tuple) and len(entry) == 2:
                obj_id, obj = entry
            else:
                obj_id, obj = None, entry
        except Exception:
            obj_id, obj = None, entry

        num_objects += 1

        if not validate_objects:
            # If validation is disabled, count everything as good.
            good_objects += 1
            continue

        try:
            # Assume a helper method _validate_object exists that returns
            # True if the object is valid, False otherwise.  It may
            # optionally verify checksums when check_digests is True.
            if getattr(self, "_validate_object", None):
                is_valid = self._validate_object(obj, check_digests=check_digests)
            else:
                # Fallback: trivially consider the object valid.
                is_valid = True

            if is_valid:
                good_objects += 1
            elif show_warnings:
                print(f"Invalid object detected: {obj_id!r}")
        except Exception as exc:  # pragma: no cover
            if show_warnings:
                print(f"Error validating object {obj_id!r}: {exc!r}")

    return num_objects, good_objects

