def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    # Helper to load an inventory file; expected to be JSON mapping from path to digest
    def _load_inventory(vdir):
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise ValueError(f"Missing inventory file in '{vdir}'. Expected '{inv_path}'.")
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except Exception as exc:
            raise ValueError(f"Failed to parse inventory in '{vdir}': {exc}") from exc
        if not isinstance(data, dict):
            raise ValueError(f"Inventory in '{vdir}' must be a mapping; got {type(data).__name__}")
        # Ensure all keys are strings and all digests are strings
        for key, val in data.items():
            if not isinstance(key, str):
                raise ValueError(f"Inventory key '{key}' in '{vdir}' is not a string")
            if not isinstance(val, str):
                raise ValueError(f"Inventory value for '{key}' in '{vdir}' is not a string")
        return data

    if not version_dirs:
        raise ValueError("No version directories provided")

    # Records of any digest differences relative to the root inventory
    self.differences = {}
    root_inventory = None
    accumulated_inventory = {}

    for idx, vdir in enumerate(version_dirs):
        inventory = _load_inventory(vdir)

        # For vdir 1, set as root
        if idx == 0:
            root_inventory = inventory
            accumulated_inventory = inventory.copy()
            continue

        # Check that all files present in earlier inventories are present in current
        missing = set(accumulated_inventory.keys()) - set(inventory.keys())
        if missing:
            missing_str = ", ".join(sorted(missing))
            raise ValueError(
                f"Inventory for '{vdir}' missing files present in earlier versions: {missing_str}"
            )

        # Record any differences compared to the root inventory
        for path, digest in inventory.items():
            root_digest = root_inventory.get(path)
            if root_digest is not None and digest != root_digest:
                self.differences.setdefault(path, []).append(
                    {"version": vdir, "current_digest": digest, "root_digest": root_digest}
                )

        # Update accumulated inventory for next iteration
        accumulated_inventory.update(inventory)

    # No return value; results are stored on self
    return None

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not all(isinstance(d, str) for d in version_dirs):
        raise TypeError("all elements of version_dirs must be strings")

    # Root inventory must be present on self
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise AttributeError("The object must have a 'root_inventory' dictionary attribute")

    # Prepare a container for differences
    differences = {}

    for dir_name in version_dirs:
        # Build full path to the inventory file for this version
        inventory_path = os.path.join(dir_name, "inventory.json")

        # Ensure the inventory file exists
        if not os.path.isfile(inventory_path):
            raise FileNotFoundError(
                f"Missing inventory file in version directory: {dir_name!r}"
            )

        try:
            with open(inventory_path, "r", encoding="utf-8") as fh:
                version_inventory = json.load(fh)
        except Exception as exc:
            raise ValueError(
                f"Failed to load inventory for '{dir_name}': {exc}"
            ) from exc

        if not isinstance(version_inventory, dict):
            raise ValueError(
                f"Inventory for '{dir_name}' must be a mapping of file -> digest"
            )

        # Verify that the version inventory contains the same set of files
        root_files = set(self.root_inventory)
        version_files = set(version_inventory)

        missing_in_version = root_files - version_files
        if missing_in_version:
            raise ValueError(
                f"Inventory in '{dir_name}' is missing files: "
                f"{', '.join(sorted(missing_in_version))}"
            )

        # Optional: If the version inventory contains files not in root, warn or raise
        extra_files = version_files - root_files
        if extra_files:
            # We raise here because having files in the inventory that are not in the root
            # inventory generally indicates a problem
            raise ValueError(
                f"Inventory in '{dir_name}' contains unknown files: "
                f"{', '.join(sorted(extra_files))}"
            )

        # Compare digests and collect differences
        for file_path, digest in version_inventory.items():
            root_digest = self.root_inventory.get(file_path)
            if digest != root_digest:
                differences.setdefault(file_path, []).append((dir_name, digest))

    # Store the differences on the instance for later validation checks
    self.version_inventory_diffs = differences

    # Return the differences dictionary for convenience
    return differences

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory paths")
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    # Helper to construct inventory file path without importing os
    def _inventory_file(dir_path):
        return dir_path if dir_path.endswith('/') else dir_path + '/'

    # Load an inventory file (simple whitespace separated path and digest)
    def _load_inventory(dir_path):
        inventory_path = _inventory_file(dir_path) + "inventory.txt"
        inventory = {}
        try:
            with open(inventory_path, "r", encoding="utf-8") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    # Expect a format: <path> <digest>
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        raise ValueError(f"Malformed inventory line in {inventory_path}: {line!r}")
                    path, digest = parts[0], parts[1]
                    inventory[path] = digest
        except FileNotFoundError as e:
            raise ValueError(f"Missing inventory file for directory {dir_path}") from e
        return inventory

    # Determine root inventory directory.  We expect an attribute on the instance.
    if not hasattr(self, "root_inventory_path"):
        raise AttributeError("Instance must have a 'root_inventory_path' attribute pointing to the root inventory directory")
    root_inventory = _load_inventory(self.root_inventory_path)

    # Record differences: {file_path: [(version_number, version_digest), ...], ...}
    differences = {}

    # Validate each version directory in sequence
    for idx, dir_path in enumerate(version_dirs, start=1):
        # Load the inventory for this version
        inv = _load_inventory(dir_path)

        # Check that the version inventory is a subset of the root inventory
        missing = [p for p in inv if p not in root_inventory]
        if missing:
            raise ValueError(f"Inventory of version {idx} (directory {dir_path}) contains files not present in the root inventory: {missing}")

        # Check digests against root
        for path, digest in inv.items():
            root_digest = root_inventory.get(path)
            if root_digest is None:
                # This case was handled by 'missing', but keep for safety
                continue
            if root_digest != digest:
                differences.setdefault(path, []).append((idx, digest))

    # Store differences for later use
    self.differences = differences
    return differences

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'    - looks like an OCFL Storage Root
        'object'  - looks like an OCFL Object
        'file'    - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path!r}"
        if os.path.isfile(path):
            return "file"

        if not os.path.isdir(path):
            return f"Path is not a file or directory: {path!r}"

        # Find files that start with '0=' (Namaste files)
        namaste_files = [f for f in os.listdir(path) if f.startswith("0=")]
        if not namaste_files:
            return "No Namaste file found"

        # If multiple Namaste files, pick the first but note ambiguity
        if len(namaste_files) > 1:
            # Attempt to determine type from each; if they disagree, return ambiguous
            types = set()
            for nf in namaste_files:
                full = os.path.join(path, nf)
                if not os.path.isfile(full):
                    continue
                try:
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        first_line = fh.readline().strip().lower()
                    if "root" in first_line:
                        types.add("root")
                    elif "object" in first_line:
                        types.add("object")
                except Exception as e:
                    continue
            if len(types) == 1:
                return types.pop()
            elif len(types) == 0:
                return "Namaste files present but no identifiable type"
            else:
                return "Ambiguous Namaste types found"
        else:
            # Single Namaste file
            full = os.path.join(path, namaste_files[0])
            try:
                with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                    first_line = fh.readline().strip().lower()
                if "root" in first_line:
                    return "root"
                if "object" in first_line:
                    return "object"
                # If it has neither, we cannot determine
                return "Namaste file found but type unknown"
            except Exception as e:
                return f"Error reading Namaste file: {e}"
    except Exception as e:
