def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'  - looks like an OCFL Storage Root
        'object'  - looks like an OCFL Object
        'file'  - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f"error: path does not exist: {path}"
    if os.path.isfile(path):
        return 'file'
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except OSError as e:
            return f"error: cannot list directory {path} ({e})"
        files = []
        for name in entries:
            full = os.path.join(path, name)
            if os.path.isfile(full):
                files.append(name)
        namaste_files = [f for f in files if f.startswith('0=')]
        if namaste_files:
            return 'object'
        else:
            return 'root'
    return f"error: unknown path type for {path}"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os, re

    if not path:
        return 'Invalid path'

    # Resolve symlinks to decide the underlying type
    try:
        stat = os.stat(path)
    except FileNotFoundError:
        return 'Path does not exist'
    except OSError as exc:
        return f'Cannot access path: {exc}'

    if os.path.isfile(path):
        return 'file'

    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except OSError as exc:
            return f'Cannot list directory: {exc}'

        # look for Namaste files that start with "0="
        for entry in entries:
            if entry.startswith('0='):
                # A Namaste file indicates this is an object directory
                return 'object'
        # No Namaste file found; treat as a root
        return 'root'

    return 'Unknown type'

