def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure params is a dictionary
    if not isinstance(params, dict):
        raise ValueError("params must be a dict")

    # If no bug ids passed, nothing to amend
    if not bug_ids:
        return params

    try:
        # Handle a single id
        if isinstance(bug_ids, (str, int)):
            params['id'] = str(bug_ids)
        # Handle iterable of ids
        elif isinstance(bug_ids, (list, tuple, set)):
            ids = [str(b) for b in bug_ids if b is not None]
            if not ids:
                return params
            if len(ids) == 1:
                params['id'] = ids[0]
            else:
                # Bugzilla expects comma‑separated list for multiple ids
                params['ids'] = ','.join(ids)
        else:
            # Unsupported type; raise a descriptive error
            raise ValueError("bug_ids must be a single id or an iterable of ids")
    except Exception:
        # If anything goes wrong, simply propagate the exception
        raise

    return params

