                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    from ruamel.yaml.nodes import MappingNode  # Imported lazily to avoid unnecessary imports

    def merge_mapping_nodes(node1, node2):
        """Recursively merge two MappingNode instances."""
        # Build a list from the first node's value
        merged_pairs = list(node1.value)
        # Map key values to their index in merged_pairs
        index_map = {k.value: i for i, (k, _) in enumerate(merged_pairs)}
        for k2, v2 in node2.value:
            idx = index_map.get(k2.value)
            if idx is not None:
                k1, v1 = merged_pairs[idx]
                if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
                    merged_pairs[idx] = (k1, merge_mapping_nodes(v1, v2))
                else:
                    merged_pairs[idx] = (k1, v2)
            else:
                merged_pairs.append((k2, v2))
        return MappingNode(tag=node1.tag, value=merged_pairs)

    key_map = {}
    for key_node, value_node in nodes:
        # Retrieve key string; guard against missing attribute
        try:
            key_str = key_node.value
        except Exception:
            continue  # Skip malformed entries
        if key_str not in key_map:
            key_map[key_str] = (key_node, value_node)
        else:
            existing_key, existing_val = key_map[key_str]
            if isinstance(existing_val, MappingNode) and isinstance(value_node, MappingNode):
                merged_val = merge_mapping_nodes(existing_val, value_node)
                key_map[key_str] = (existing_key, merged_val)
            else:
                key_map[key_str] = (existing_key, value_node)
    # Preserve insertion order
    return list(key_map.values())

