    string.
    """
    flags = []
    try:
        for action in parser._actions:
            # option_strings is present for optional arguments
            if hasattr(action, 'option_strings'):
                for opt in action.option_strings:
                    if opt.startswith('-'):
                        flags.append(opt)
    except Exception:
        return ''
    # Preserve order while removing duplicates
    seen = set()
    unique_flags = []
    for f in flags:
        if f not in seen:
            seen.add(f)
            unique_flags.append(f)
    return ' '.join(unique_flags)

