def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse
    try:
        # Assuming that a global parser instance named `parser` is defined elsewhere
        from __main__ import parser  # This line attempts to import the parser from the script's main module
    except (ImportError, AttributeError):
        try:
            # If this file is the main script, the global namespace is __main__
            parser  # noqa: F821
        except NameError:
            raise RuntimeError("An argparse.ArgumentParser named 'parser' must be defined in the global scope.") from None

    # Flatten the arguments into a single list of strings
    args = list(unparsed_arguments)

    # Parse known arguments, ignoring unknown ones
    try:
        ns, _ = parser.parse_known_args(args)
    except Exception as exc:
        raise RuntimeError(f"Argument parsing failed: {exc}") from exc

    # Determine if a subparser was used
    subparsers_action = getattr(parser, '_subparsers', None)
    subparser_name = None
    if subparsers_action is not None:
        dest_name = getattr(subparsers_action, 'dest', None)
        if dest_name:
            subparser_name = getattr(ns, dest_name, None)

    # Map the parsed namespace to the appropriate key
    key = subparser_name if subparser_name else 'global'
    return {key: ns}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_results = {}
    all_remaining = []

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
        except SystemExit:
            # If parser fails (e.g. required arguments missing), treat as empty parse.
            namespace = argparse.Namespace()
            remaining = list(unparsed_arguments)
        parsed_results[name] = namespace
        all_remaining.append(remaining)

    if not all_remaining:
        # No subparsers provided
        return parsed_results, list(unparsed_arguments)

    # Determine arguments not claimed by any subparser (intersection of remaining lists)
    common_remaining_set = set(all_remaining[0])
    for rem in all_remaining[1:]:
        common_remaining_set.intersection_update(rem)

    # Preserve original order from the first remaining list
    remaining_unclaimed = [arg for arg in all_remaining[0] if arg in common_remaining_set]

    return parsed_results, remaining_unclaimed

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if response is None:
        raise ValueError("response cannot be None")
    if not isinstance(response, (list, tuple)):
        raise TypeError(f"response must be a list or tuple, got {type(response).__name__}")
    if not isinstance(max_results, int):
        raise TypeError(f"max_results must be an int, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    for start in range(0, len(response), max_results):
        yield response[start:start + max_results]

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    from collections import Counter
    cumulative = Counter()
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        cumulative.update(d)
    return dict(cumulative)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if not hasattr(dicts, '__iter__'):
        raise TypeError("dicts must be an iterable of dictionaries")
    result = {}
    for idx, d in enumerate(dicts):
        if not isinstance(d, dict):
            raise TypeError(f"Element #{idx} is not a dict: {repr(d)}")
        for key, val in d.items():
            # Accumulate numeric values; if not numeric, attempt to add (will raise if incompatible)
            result[key] = result.get(key, 0) + val
    return result

