def was_processed(processed, path_name, verbose):
    """Check if a file or directory has already been processed.

    To prevent recursion, expand the path name to an absolute path
    call this function with a set that will store all the entries and
    the entry to test. If the entry is already in the set, report the issue
    and return ``True``. Otherwise, add the entry to the set and return
    ``False`` to allow the path to be processed.

    Args:
        processed: Set to store processed pathnames
        path_name: Path to a directory or file
        verbose: True if verbose output is requested

    Returns:
        True if it's already in the set. False if not.
    """
    # Validate inputs
    if not isinstance(processed, set):
        if verbose:
            print('[was_processed] processed is not a set: %r' % processed)
        raise TypeError('processed argument must be a set')
    if not isinstance(path_name, (bytes, str)):
        if verbose:
            print('[was_processed] path_name is not a string: %r' % path_name)
        raise TypeError('path_name must be a string or bytes')

    try:
        # Normalize to absolute path
        abs_path = os.path.abspath(path_name)
    except Exception as e:
        if verbose:
            print('[was_processed] error normalizing path %r: %s' % (path_name, e))
        return False

    if abs_path in processed:
        if verbose:
            print('[was_processed] path already processed: %s' % abs_path)
        return True
    else:
        try:
            processed.add(abs_path)
        except Exception as e:
            if verbose:
                print('[was_processed] error adding path to set: %s' % e)
            # Even if we couldn't add, we should still consider it not processed
            return False
        return False

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("number must be non‑negative")

    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("alphabet must be a list or tuple of characters")

    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two characters")

    # Ensure alphabet elements are unique single-character strings
    if len(set(alphabet)) != base:
        raise ValueError("alphabet must contain unique characters")
    for ch in alphabet:
        if not isinstance(ch, str):
            raise TypeError("alphabet elements must be strings")
        if len(ch) != 1:
            raise ValueError("alphabet elements must be single characters")

    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None")
        if padding < 0:
            raise ValueError("padding must be non‑negative")

    # Conversion
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    # Padding (prepend with the zero character)
    if padding is not None and len(digits) < padding:
        digits = [alphabet[0]] * (padding - len(digits)) + digits

