    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Ensure destination_path is a directory
    try:
        if destination_path.exists():
            if not destination_path.is_dir():
                raise RuntimeError(f"Destination path {destination_path} exists and is not a directory.")
        else:
            destination_path.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        raise RuntimeError(f"Failed to create destination directory {destination_path}: {exc}") from exc

    # Download the archive to a temporary file
    try:
        tmp_fd, tmp_path = tempfile.mkstemp(suffix=".tar.gz")
        os.close(tmp_fd)  # Will write using a file handle opened later
        with requests.get(url, stream=True, timeout=30) as r:
            r.raise_for_status()
            with open(tmp_path, 'wb') as f:
                for chunk in r.iter_content(chunk_size=8192):
                    if chunk:
                        f.write(chunk)
    except requests.exceptions.RequestException as exc:
        raise RuntimeError(f"Failed to download archive from {url}: {exc}") from exc
    except OSError as exc:
        raise RuntimeError(f"Failed to write temporary file {tmp_path}: {exc}") from exc

    # Extract the tar archive
    try:
        with tarfile.open(tmp_path, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except (tarfile.TarError, OSError) as exc:
        raise RuntimeError(f"Failed to extract archive {tmp_path}: {exc}") from exc
    finally:
        # Clean up temporary file
        try:
            os.remove(tmp_path)
        except OSError:
            pass

    return destination_path

