def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    import shlex

    # Resolve auto platform
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1

    # Use shlex with appropriate mode; shlex.posix=False mimics Windows quoting
    if platform == 1:
        return shlex.split(s, posix=True)
    elif platform == 0:
        return shlex.split(s, posix=False)
    else:
        raise ValueError(f"Unsupported platform value: {platform!r}")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    # ensure input is a string
    if not isinstance(s, str):
        raise TypeError(f"s must be a string, got {type(s).__name__}")

    # resolve autopurupl
    if platform == 'this':
        try:
            import platform as _pl
            platform = 0 if _pl.system() == 'Windows' else 1
        except Exception:
            platform = 1
    try:
        platform = int(platform)
    except Exception:
        platform = 1

    try:
        if platform == 0:  # Windows/CMD style
            win_pat = re.compile(r'''
                "(?:\\.|[^"\\])*"   # quoted sequence
                | [^ \t]+           # unquoted token
            ''', re.VERBOSE)
            parts = win_pat.findall(s)
            res = []
            for part in parts:
                if part[0] == '"':
                    inner = part[1:-1]
                    # remove escape sequences
                    # double quotes inside can be escaped with \"
                    inner = re.sub(r'\\(.)', r'\1', inner)
                else:
                    inner = part
                res.append(inner)
            return res
        else:  # POSIX style
            posix_pat = re.compile(r'''
                "(?:\\.|[^"\\])*"   # double quoted string
                | '(?:\\.|[^'\\])*' # single quoted string
                | [^\s]+            # unquoted token
            ''', re.VERBOSE)
            parts = posix_pat.findall(s)
            res = []
            for part in parts:
                if part[0] in ('"', "'"):
                    inner = part[1:-1]
                    # unescape backslashes
                    inner = re.sub(r'\\(.)', r'\1', inner)
                else:
                    inner = re.sub(r'\\(.)', r'\1', part)
                res.append(inner)
            return res
    except Exception:
        # Fallback: use shlex.split with appropriate posix flag
        try:
            import shlex
            return shlex.split(s, posix=(platform != 0))
        except Exception as exc:
            raise ValueError(f"Failed to split '{s}': {exc}") from exc

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    # Determine platform type
    plt = platform
    if platform == 'this':
        try:
            import sys
            plt = 0 if sys.platform.startswith('win') else 1
        except Exception:
            plt = 1  # default to POSIX
    args = []
    if plt == 1:  # POSIX
        # Simple regex: capture quoted or unquoted words
        token_re = re.compile(r'''"([^"]*)"|\'([^\']*)\'|(\S+)''')
        for m in token_re.finditer(s):
            if m.group(1) is not None:
                args.append(m.group(1))
            elif m.group(2) is not None:
                args.append(m.group(2))
            else:
                args.append(m.group(3))
    else:  # Windows
        i = 0
        length = len(s)
        while i < length:
            # Skip whitespace
            while i < length and s[i].isspace():
                i += 1
            if i >= length:
                break
            if s[i] == '"':
                i += 1
                token = []
                backslashes = 0
                while i < length:
                    ch = s[i]
                    if ch == '\\':
                        backslashes += 1
                        i += 1
                        continue
                    if ch == '"' and backslashes % 2 == 0:
                        # End of quoted part
                        token.append('\\' * (backslashes // 2))
                        i += 1
                        break
                    else:
                        token.append('\\' * (backslashes // 2))
                        token.append(ch)
                        backslashes = 0
                        i += 1
                else:
                    # Unterminated quote - treat rest as part of token
                    pass
                args.append(''.join(token))
                # After a quoted token, continue to next token
            else:
                token = []
                while i < length and not s[i].isspace():
                    token.append(s[i])
                    i += 1
                args.append(''.join(token))
    return args

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess
    import uuid

    # Resolve and validate archive path
    archive_path = os.path.abspath(str(archive_path))
    if not os.path.isfile(archive_path):
        raise FileNotFoundError(f"Archive file does not exist: {archive_path}")

    # Resolve temporary path
    tmp_path = os.path.expanduser(str(tmp_path))
    if not os.path.isdir(tmp_path):
        os.makedirs(tmp_path, mode=0o700, exist_ok=True)

    # Decide on directory name for extraction
    if filename:
        repo_dir_name = filename.strip()
    else:
        base_name = os.path.basename(archive_path)
        # Strip common extensions
        for ext in ('.tar.gz', '.tgz', '.tar.bz2', '.tbz2', '.tar', '.zip'):
            if base_name.endswith(ext):
                base_name = base_name[: -len(ext)]
                break
        repo_dir_name = base_name or uuid.uuid4().hex

    repo_dir = os.path.join(tmp_path, repo_dir_name)

    if os.path.exists(repo_dir):
        raise FileExistsError(f"Extraction target already exists: {repo_dir}")

    os.makedirs(repo_dir, mode=0o700)

    # Determine extraction command based on file type
    if archive_path.endswith(('.tar.gz', '.tgz', '.tar.bz2', '.tbz2', '.tar')):
        cmd = ['tar', '-xf', archive_path, '-C', repo_dir]
    elif archive_path.endswith('.zip'):
        cmd = ['unzip', '-q', archive_path, '-d', repo_dir]
    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

    try:
        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError as exc:
        # Clean up partially extracted files
        if os.path.isdir(repo_dir):
            try:
                import shutil
                shutil.rmtree(repo_dir)
            except Exception:
                pass
        raise OSError(f"Extraction failed for {archive_path}: {exc}") from exc

    return f"file://{os.path.abspath(repo_dir)}"

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Validate input types
    if not isinstance(archive_path, str):
        raise TypeError(f"archive_path must be a str, got {type(archive_path).__name__}")
    if not os.path.isfile(archive_path):
        raise FileNotFoundError(f"Archive file does not exist: {archive_path}")

    # Resolve temporary path
    tmp_dir = str(tmp_path)
    try:
        os.makedirs(tmp_dir, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Could not create temporary directory '{tmp_dir}': {exc}") from exc

    # Determine destination directory name
    if filename is None:
        base = os.path.basename(archive_path)
        # Strip common archive suffixes
        suffixes = [
            ".tar.gz", ".tgz",
            ".tar.bz2", ".tbz2",
            ".tar.xz", ".txz",
            ".zip", ".tar", ".gz", ".bz2", ".xz"
        ]
        lowered = base.lower()
        for sfx in suffixes:
            if lowered.endswith(sfx):
                base = base[: -len(sfx)]
                break
        filename = base
    dest_dir = os.path.join(tmp_dir, filename)

    if os.path.exists(dest_dir):
        raise FileExistsError(f"Destination directory already exists: {dest_dir}")

    try:
        os.makedirs(dest_dir, exist_ok=False)
    except Exception as exc:
        raise OSError(f"Could not create extraction directory '{dest_dir}': {exc}") from exc

    # Unpack the archive using the standard library
    try:
        shutil.unpack_archive(archive_path, dest_dir)
    except Exception as exc:
        try:
            shutil.rmtree(dest_dir, ignore_errors=True)
        except Exception:
            pass
        raise RuntimeError(f"Failed to unpack archive '{archive_path}': {exc}") from exc

    return f"file://{os.path.abspath(dest_dir)}"

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files,
    return those files as a single string with each filename separated by a comma."""
    # Build the git command to list ignored files
    cmd = ['git', 'ls-files', '--others', '--ignored', '--exclude-standard']
    if ignored:
        # If `ignored` is a list of additional git arguments, extend the command
        if isinstance(ignored, (list, tuple)):
            cmd.extend(ignored)
        else:
            # Treat single string argument as an additional git flag or path
            cmd.append(ignored)
    try:
        output = subprocess.check_output(cmd, stderr=subprocess.STDOUT, text=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"git command failed: {e.output}") from e
    # Convert output into a sorted list of filenames
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    # Return a comma-separated string of filenames
    return ','.join(files)

