def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    # Handle None or "always" (case-insensitive)
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError("frequency must be a string or None")
    trimmed = frequency.strip()
    if trimmed.lower() == "always":
        return None
    if trimmed == "":
        raise ValueError("empty frequency string")

    # Split into numeric and unit parts
    parts = trimmed.split()
    if len(parts) != 2:
        raise ValueError(f"invalid frequency format: '{frequency}'")
    num_part, unit_part = parts
    try:
        quantity = int(num_part)
    except ValueError:
        raise ValueError(f"invalid numeric value in frequency: '{num_part}'")

    unit = unit_part.lower()
    # Normalize unit (accept plurals and abbreviations)
    if unit in {"year", "years"}:
        return datetime.timedelta(days=quantity * 365)
    if unit in {"month", "months"}:
        return datetime.timedelta(days=quantity * 30)
    if unit in {"week", "weeks"}:
        return datetime.timedelta(weeks=quantity)
    if unit in {"day", "days"}:
        return datetime.timedelta(days=quantity)
    if unit in {"hour", "hours"}:
        return datetime.timedelta(hours=quantity)
    if unit in {"minute", "minutes", "min"}:
        return datetime.timedelta(minutes=quantity)
    if unit in {"second", "seconds", "sec"}:
        return datetime.timedelta(seconds=quantity)

    raise ValueError(f"unknown time unit in frequency: '{unit_part}'")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    ft = frequency.strip()
    if ft.lower() == 'always':
        return None
    try:
        import re
    except Exception:
        raise ValueError('Required module re not available')
    m = re.fullmatch(r'(\d+)\s*([a-zA-Z]+)', ft)
    if not m:
        raise ValueError(f'Unable to parse frequency: {frequency!r}')
    amount = int(m.group(1))
    unit = m.group(2).lower()
    if unit in ('day', 'days'):
        return datetime.timedelta(days=amount)
    if unit in ('hour', 'hours'):
        return datetime.timedelta(hours=amount)
    if unit in ('minute', 'minutes'):
        return datetime.timedelta(minutes=amount)
    if unit in ('second', 'seconds'):
        return datetime.timedelta(seconds=amount)
    if unit in ('week', 'weeks'):
        return datetime.timedelta(weeks=amount)
    if unit in ('month', 'months'):
        return datetime.timedelta(days=30 * amount)
    if unit in ('year', 'years'):
        return datetime.timedelta(days=365 * amount)
    raise ValueError(f'Unknown time unit in frequency: {unit!r}')

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Direct string comparison for common localhost identifiers
    if host in ("localhost", "127.0.0.1", "::1"):
        return True

    try:
        # Resolve the host to all IP addresses (IPv4 + IPv6)
        for info in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = info
            if family == socket.AF_INET:
                addr = sockaddr[0]
                # IPv4 loopback addresses are in the 127.0.0.0/8 block
                if addr == "127.0.0.1" or addr.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                addr = sockaddr[0]
                # IPv6 loopback address
                if addr == "::1":
                    return True
    except socket.gaierror:
        # Cannot resolve hostname; not considered local
        return False

    return False

