def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    # Only Windows platforms can have Git Bash
    if os.name != "nt":
        return False

    env = os.environ

    # Check common environment variables set by Git Bash
    if "MSYSTEM" in env:
        return True
    if "OSTYPE" in env:
        # Some installations set OSTYPE to msys, mingw, or cygwin
        return env["OSTYPE"].lower().startswith(("msys", "mingw", "cygwin"))

    # Look in the PATH for typical Git Bash directory names
    path_dirs = env.get("PATH", "").split(os.pathsep)
    for d in path_dirs:
        if d.lower().startswith(("mingw", "msys", "cygwin")):
            return True

    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    '''
    # Expand user tilde in the path
    config_path = os.path.expanduser(config_filename)

    # If the file exists and we don't want to overwrite, abort
    if not overwrite and os.path.isfile(config_path):
        return

    # Ensure the directory exists
    dir_path = os.path.dirname(config_path)
    if dir_path:
        try:
            os.makedirs(dir_path, exist_ok=True)
        except OSError as exc:
            # If directory creation fails and the path is not a directory, re‑raise
            if not os.path.isdir(dir_path):
                raise exc

    # Write the rendered configuration to the file
    try:
        with open(config_path, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        # Set the file permission mode as requested
        try:
            os.chmod(config_path, mode)
        except OSError:
            # If changing mode fails (e.g., on read‑only FS), ignore silently
            pass
    except OSError as e:
        # Propagate any I/O error
        raise e

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    config_filename = os.path.expanduser(config_filename)
    if not overwrite and os.path.isfile(config_filename):
        return
    # ensure parent directories exist
    parent_dir = os.path.dirname(config_filename)
    if parent_dir:
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except OSError as exc:
            if not os.path.isdir(parent_dir):
                raise
    # coerce rendered_config to string
    if rendered_config is None:
        content = ''
    else:
        content = str(rendered_config)
    # write file
    try:
        with open(config_filename, 'w', encoding='utf-8') as f:
            f.write(content)
    except OSError as exc:
        raise
    # set file permissions
    try:
        os.chmod(config_filename, mode)
    except OSError:
        pass
    return config_filename

def _resolve_string(matcher):
    '''Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.'''
    # Determine name and default from matcher
    if isinstance(matcher, (tuple, list)):
        if len(matcher) == 0:
            raise TypeError("Matcher tuple/list must contain at least the variable name")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        # Assume an object with 'name' and optional 'default' attributes
        try:
            name = matcher.name
        except AttributeError:
            raise TypeError("Matcher must provide a 'name' attribute or be a tuple/list with the name as its first element")
        default = getattr(matcher, 'default', None)

    if not isinstance(name, str):
        raise TypeError(f"Variable name must be a string, got {type(name).__name__}")

