def run_command(commands, args=None, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, shlex, os

    # Validate and build command list
    if isinstance(commands, str):
        command = shlex.split(commands)
    elif isinstance(commands, (list, tuple)):
        command = list(commands)
    else:
        raise TypeError("commands must be a str or list/tuple")

    if args is not None:
        if isinstance(args, str):
            arg_list = shlex.split(args)
        elif isinstance(args, (list, tuple)):
            arg_list = list(args)
        else:
            raise TypeError("args must be a str or list/tuple")
        command.extend(arg_list)

    if verbose:
        print(f"Running command: {' '.join(command)}")

    # Prepare environment
    env_combined = os.environ.copy()
    if env:
        if not isinstance(env, dict):
            raise TypeError("env must be a dict")
        env_combined.update(env)

    # Execute command
    try:
        result = subprocess.run(
            command,
            cwd=cwd,
            env=env_combined,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
            text=True,
            check=False,
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {command[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run command {' '.join(command)}") from e

    # Check return code
    if result.returncode != 0:
        stderr_msg = result.stderr if not hide_stderr else ""
        raise RuntimeError(
            f"Command {' '.join(command)} failed with exit code {result.returncode}\nstdout: {result.stdout}\nstderr: {stderr_msg}"
        )

    return result

