def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Handle string or bytes directly
    if isinstance(seq, (str, bytes)):
        # If bytes, convert to string
        if isinstance(seq, bytes):
            try:
                seq_str = seq.decode()
            except Exception:
                seq_str = str(seq)
        else:
            seq_str = seq
        return seq_str, seq_str.__class__.__name__

    # Handle file-like objects (something with a read method)
    if hasattr(seq, "read"):
        try:
            # Try to use the provided buffer size if any
            if bufsize is not None:
                data = seq.read(bufsize)
            else:
                data = seq.read()
        except Exception as exc:
            raise TypeError(f"Unable to read from file-like object: {exc}") from exc
        # If read returns bytes, convert to string
        if isinstance(data, bytes):
            try:
                data = data.decode()
            except Exception:
                data = str(data)
        return data, "file"

    # Handle list or tuple of characters (or other iterable)
    if isinstance(seq, (list, tuple)):
        try:
            # Try to join elements into a string, supporting non-string elements by converting them
            seq_str = "".join(str(x) for x in seq)
            return seq_str, "string"
        except Exception as exc:
            raise TypeError(f"Cannot convert list/tuple into string: {exc}") from exc

    # If seq is an iterable but not a sequence type, try to join into string
    try:
        if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
            seq_str = "".join(str(x) for x in seq)
            return seq_str, "string"
    except Exception:
        pass

    # Fallback: return the original object and its type name
    return seq, seq.__class__.__name__

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise ValueError('seq cannot be None')
    # If seq is an iterable that is not a string/bytes, consider it a sequence
    if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
        return seq, type(seq)
    # Otherwise convert to a list, optionally batching with bufsize
    if bufsize is None or bufsize <= 0:
        return list(seq), type(seq)
    # Buffer the input in chunks of size bufsize
    result = []
    it = iter(seq)
    try:
        while True:
            # Build a chunk of at most bufsize items
            chunk = []
            for _ in range(bufsize):
                chunk.append(next(it))
            result.extend(chunk)
    except StopIteration:
        pass
    return result, type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type)."""
    # If *seq* is already a concrete sequence type, return it unchanged
    if isinstance(seq, (list, tuple, set, bytes, bytearray, memoryview)):
        return (seq, type(seq))
    # Attempt to obtain an iterator; if that fails we treat *seq* as a singleton
    try:
        it = iter(seq)
    except TypeError:
        return (seq, type(seq))
    # If the caller supplied a buffer size, read at most that many elements
    if bufsize is not None:
        if not isinstance(bufsize, int) or bufsize < 0:
            raise ValueError("bufsize must be a non‑negative integer or None")
        seq_list = []
        try:
            for _ in range(bufsize):
                seq_list.append(next(it))
        except StopIteration:
            pass
    else:
        seq_list = list(it)
    return (seq_list, type(seq))

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    if seq is None:
        raise ValueError("No sequence provided")

    # Handle string or bytes (sequence content)
    if isinstance(seq, (str, bytes)):
        sequence = seq.decode() if isinstance(seq, bytes) else seq
        seq_type = "string"
        return sequence, seq_type

    # Handle already-sequence types like list, tuple, set, bytearray
    if isinstance(seq, (list, tuple, set, bytearray)):
        sequence = seq
        seq_type = type(seq).__name__
        return sequence, seq_type

    # Handle file-like objects
    if hasattr(seq, "read"):
        try:
            parts = []
            if bufsize:
                while True:
                    chunk = seq.read(bufsize)
                    if not chunk:
                        break
                    parts.append(chunk)
            else:
                parts.append(seq.read())
            raw = "".join(parts)
            sequence = raw
            seq_type = "file"
            return sequence, seq_type
        except Exception as exc:
            raise ValueError(f"Unable to read sequence from file-like object {seq!r}: {exc}") from exc

    # Handle generic iterables / generators
    try:
        # Consume iterable into a string
        sequence = "".join(list(seq))
        seq_type = "iterator"
        return sequence, seq_type
    except Exception as exc:
        raise ValueError(f"Unable to derive sequence from iterable {seq!r}: {exc}") from exc

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Return current scale if no other provided
        if other is None:
            return getattr(self, "_scale", None)

        # Validate numeric input
        try:
            target_scale = float(other)
        except Exception:
            raise TypeError("Scale must be a numeric value")

        # Current scale must exist and be non-zero
        current_scale = getattr(self, "_scale", None)
        if current_scale is None or current_scale == 0:
            raise ValueError(
                "Cannot rescale graph with unknown or zero current scale"
            )

        # Compute scaling factor
        factor = target_scale / current_scale

        # Rescale last coordinate and its associated error if they exist
        # Expect that coordinate arrays are stored in a list or tuple
        # named `coordinates` and associated errors in `errors`.
        coordinates = getattr(self, "coordinates", None)
        errors = getattr(self, "errors", None)

        # Apply factor to last coordinate
        if coordinates and isinstance(coordinates, (list, tuple)):
            try:
                coordinates[-1] = coordinates[-1] * factor
            except Exception:
                # If coordinates are not Numpy arrays, try generic iteration
                try:
                    coordinates[-1] = [v * factor for v in coordinates[-1]]
                except Exception:
                    pass  # Leave unchanged if not multiplicative

        # Rescale corresponding errors if present
        if errors and isinstance(errors, (list, tuple)):
            try:
                errors[-1] = errors[-1] * abs(factor)
            except Exception:
                try:
                    errors[-1] = [e * abs(factor) for e in errors[-1]]
                except Exception:
                    pass  # Leave unchanged if not multiplicative

        # Update the graph's scale attribute
        self._scale = target_scale
        return None"

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph or a list of points if a graph type cannot be created.
    """
    # Validate get_coordinate argument
    allowed_coords = {"left", "right", "middle"}
    if get_coordinate not in allowed_coords:
        raise ValueError(f"get_coordinate must be one of {allowed_coords}")

    # Attempt to obtain edges and values from the histogram object
    edges = None
    values = None

    # If hist is a dict-like container
    if isinstance(hist, dict):
        if "edges" in hist:
            edges = hist["edges"]
        elif "bin_edges" in hist:
            edges = hist["bin_edges"]
        elif hasattr(hist, "xedges"):
            edges = hist["xedges"]
        if "values" in hist:
            values = hist["values"]
        elif "contents" in hist:
            values = hist["contents"]
        elif "data" in hist:
            values = hist["data"]

    # If hist is an object with attributes
    if edges is None or values is None:
        for attr in ("edges", "bin_edges", "xedges", "edges_"):
            if getattr(hist, attr, None) is not None:
                edges = getattr(hist, attr)
                break
        for attr in ("values", "contents", "data", "y"):
            if getattr(hist, attr, None) is not None:
                values = getattr(hist, attr)
                break

    # If still not found, check if hist is iterable of (left, right, value)
    if edges is None or values is None:
        try:
            iterator = iter(hist)
        except TypeError:
            iterator = None

        if iterator is not None:
            lefts = []
            values = []
            for bin_obj in iterator:
                if isinstance(bin_obj, tuple) and len(bin_obj) == 3:
                    l, r, v = bin_obj
                    lefts.append(l)
                    values.append(v)
                else:
                    raise ValueError(
                        "Histogram iterable items must be three-element tuples "
                        "(left_edge, right_edge, value)."
                    )
            if len(lefts) < 1:
                raise ValueError("Histogram iterable is empty.")
            # Build edges from the lefts; assume constant bin width
            if len(lefts) > 1:
                step = lefts[1] - lefts[0]
                edges = lefts + [lefts[-1] + step]
            else:
                raise ValueError("Cannot infer edges from a single bin.")
    if edges is None or values is None:
        raise ValueError("Unable to determine edges and values from histogram.")

    # Ensure edges and values are list-like and of compatible length
    try:
        edges = list(edges)
        values = list(values)
    except TypeError:
        raise ValueError("Edges and values must be iterable.")

    if len(values) + 1 != len(edges):
        raise ValueError(
            f"Number of edges ({len(edges)}) must be one greater than number of values ({len(values)})."
        )

    # Assemble points according to get_coordinate and make_value
    points = []
    for i, val in enumerate(values):
        left = edges[i]
        right = edges[i + 1]
        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        else:  # middle
            coord = 0.5 * (left + right)
        processed = make_value(val) if make_value else val
        if isinstance(processed, (list, tuple)):
            point_tuple = (coord,) + tuple(processed)
        else:
            point_tuple = (coord, processed)
        if len(point_tuple) != len(field_names):
            raise ValueError(
                f"Produced point has {len(point_tuple)} values, "
                f"expected {len(field_names)}."
            )
        points.append(point_tuple)

    # Resolve scale argument
    graph_scale = scale
    if scale is True:
        graph_scale = getattr(hist, "scale", None)

    # Try to construct a graph object if available
    try:
        # Assume a Graph class is available in the current namespace
        graph = Graph(field_names=field_names, scale=graph_scale)
        # Append points; support add_point, append, or extend methods
        for pt in points:
            if hasattr(graph, "add_point"):
                graph.add_point(pt)
            elif hasattr(graph, "append"):
                graph.append(pt)
            else:
                raise AttributeError(
                    "Graph object lacks add_point or append methods."
                )
        return graph
    except Exception:
        # Fallback: return points as a list of dicts keyed by field_names
        return [dict(zip(field_names, pt)) for pt in points]

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    errors = []

    # 1. Check that candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"{candidate!r} does not provide interface {iface!r}"
                )
        except Exception as exc:
            errors.append(
                f"Failed to check providedBy for {candidate!r}: {exc}"
            )

    # 2. Check methods
    try:
        methods = iface.methods()  # returns dict of name: method
    except Exception:
        methods = {}

    for name, iface_method in methods.items():
        # Ensure the candidate has the attribute
        if not hasattr(candidate, name):
            errors.append(f"Missing method '{name}' in {candidate!r}")
            continue

        cand_attr = getattr(candidate, name)
        if not callable(cand_attr):
            errors.append(f"Attribute '{name}' in {candidate!r} is not callable")
            continue

        # Compare signatures if possible
        try:
            iface_sig = inspect.signature(iface_method)
        except Exception:
            iface_sig = None

        if iface_sig is not None:
            try:
                # Get the candidate function object; for bound methods
                # the signature incl. 'self' so we strip it for comparison
                if hasattr(cand_attr, "__func__"):
                    cand_func = cand_attr.__func__
                else:
                    cand_func = cand_attr
                cand_sig = inspect.signature(cand_func)
            except Exception:
                cand_sig = None

            if cand_sig is not None:
                # Strip 'self' from both signatures if present
                def strip_self(sig):
                    params = list(sig.parameters.values())
                    if params and params[0].name == "self":
                        params = params[1:]
                    return inspect.Signature(parameters=params)

                iface_sig = strip_self(iface_sig)
                cand_sig = strip_self(cand_sig)
                if iface_sig != cand_sig:
                    errors.append(
                        f"Signature mismatch for method '{name}' in {candidate!r}:\n"
                        f"  expected: {iface_sig}\n"
                        f"  actual:   {cand_sig}"
                    )

    # 3. Check attributes
    try:
        attrs = iface.attributes  # set or dict of attribute names
    except Exception:
        attrs = []

    for attr_name in attrs:
        if not hasattr(candidate, attr_name):
            errors.append(f"Missing attribute '{attr_name}' in {candidate!r}")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0], iface=iface, obj=candidate)
        else:
            raise zope.interface.Invalid("\n".join(errors), iface=iface, obj=candidate)

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    missing = []

    # 1. Verify that candidate declares it provides iface (unless tentative)
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid(
                    f"{candidate!r} does not provide {iface!r}"
                )
        except Exception:
            # try with the class if instance was passed
            if not iface.providedBy(candidate.__class__):
                raise zope.interface.Invalid(
                    f"{candidate!r} does not provide {iface!r}"
                )

    # 2. Check that all required methods exist
    # iface.methods() returns a dict: name -> zope.interface.Attribute or Attribute
    try:
        funcs = iface.methods()
    except Exception:
        funcs = {}

    for name, expected in funcs.items():
        if not hasattr(candidate, name):
            missing.append(f"Missing method {name!r}")
            continue
        cand = getattr(candidate, name)

        # Attempt a basic signature check: compare parameter lists if possible
        # This works for normal functions and method descriptors.
        has_sig = False
        sig_match = True
        if hasattr(expected, "signature") and hasattr(cand, "__signature__"):
            has_sig = True
            sig_match = expected.signature == cand.__signature__
        elif hasattr(expected, "__code__") and hasattr(cand, "__code__"):
            # Compare names of arguments
            try:
                has_sig = True
                # Use co_varnames but ignore 'self' / 'cls' differences
                iface_args = expected.__code__.co_varnames[
                    : expected.__code__.co_argcount
                ]
                cand_args = cand.__code__.co_varnames[
                    : cand.__code__.co_argcount
                ]
                # Normalise argument names by stripping 'self' or 'cls' if present
                if iface_args and iface_args[0] in ("self", "cls"):
                    iface_args = iface_args[1:]
                if cand_args and cand_args[0] in ("self", "cls"):
                    cand_args = cand_args[1:]
                sig_match = iface_args == cand_args
            except Exception:
                sig_match = False

        if has_sig and not sig_match:
            missing.append(f"Method {name!r} signature mismatch")

    # 3. Check that all required attributes exist
    try:
        attrs = iface.attributes()
    except Exception:
        attrs = {}
    for name in attrs:
        if not hasattr(candidate, name):
            missing.append(f"Missing attribute {name!r}")

    # 4. Report any errors
    if missing:
        if len(missing) == 1:
            raise zope.interface.Invalid(missing[0])
        # Join multiple messages
        raise zope.interface.Invalid("; ".join(missing))

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    errors = []

    # 1. Provided check (unless tentative)
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append("candidate does not advertise that it provides %s" % iface)
        except Exception:
            # providedBy might not exist or fail; treat as error
            errors.append("candidate does not advertise that it provides %s" % iface)

    # Helper to try to get interface signature if available
    def _get_iface_signature(method):
        # zope.interface 4.x stores signatures in the _signature attribute of the method
        try:
            sig = getattr(method, "_signature", None)
            if sig is not None:
                # _signature is a string; convert to inspect.Signature
                return inspect.signature(eval(sig))
        except Exception:
            pass
        return None

    # 2 & 3. Methods check and signature verification
    try:
        methods = getattr(iface, "methods", {})
    except Exception:
        methods = {}
    if isinstance(methods, (list, tuple)):
        # older interfaces might expose a list of method names
        method_names = methods
    else:
        # Expect a dict mapping names to methods
        method_names = methods.keys() if hasattr(methods, "keys") else []

    for name in method_names:
        if not hasattr(candidate, name):
            errors.append("missing method %s" % name)
            continue
        # Attempt signature check
        iface_method = None
        try:
            iface_method = iface.getMethod(name)
        except Exception:
            # Some interfaces expose methods via attribute lookup
            iface_method = getattr(iface, name, None)
        if iface_method is None:
            continue  # No interface method object; skip signature check
        iface_sig = _get_iface_signature(iface_method)
        try:
            cand_sig = inspect.signature(getattr(candidate, name))
        except Exception:
            cand_sig = None
        if iface_sig is not None and cand_sig is not None:
            if iface_sig != cand_sig:
                errors.append("signature mismatch for %s: expected %s, got %s" % (
                    name, iface_sig, cand_sig))

    # 4. Attributes check
    try:
        attrs = getattr(iface, "attributes", {})
    except Exception:
        attrs = {}
    if isinstance(attrs, (list, tuple)):
        attr_names = attrs
    else:
        attr_names = attrs.keys() if hasattr(attrs, "keys") else []

    for name in attr_names:
        if not hasattr(candidate, name):
            errors.append("missing attribute %s" % name)

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("Multiple interface errors: %s" % "; ".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Sanity check: iface should be a class or type
    if not isinstance(iface, type):
        raise TypeError("iface must be a class type")

    # Determine the candidate type: class or instance
    is_class_candidate = isinstance(candidate, type)

    # 1. Direct subclass/instance check
    try:
        if is_class_candidate:
            if issubclass(candidate, iface):
                return True
        else:
            if isinstance(candidate, iface):
                return True
    except Exception:
        # Any error (e.g., not comparable types) is ignored here
        pass

    # 2. Check abstract methods, if any
    abstract_methods = getattr(iface, "__abstractmethods__", set())
    if abstract_methods:
        for name in abstract_methods:
            # Obtain the attribute on the candidate; use fallback if candidate is a class
            try:
                attr = getattr(candidate, name)
            except Exception:
                if tentative:
                    return False
                raise TypeError(f"Candidate {candidate!r} does not implement abstract method '{name}'")

            if not callable(attr):
                if tentative:
                    return False
                raise TypeError(f"Candidate {candidate!r} method '{name}' is not callable")

    # 3. Fallback: if candidate is None or not a valid object
    if candidate is None:
        if tentative:
            return False
        raise TypeError("candidate cannot be None")

    # If all checks passed, candidate satisfies the interface
    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # iterate over attributes defined on the interface
    for name in dir(iface):
        # skip private and special attributes
        if name.startswith("_"):
            continue
        iface_attr = getattr(iface, name)
        # Check presence on candidate
        if not hasattr(candidate, name):
            if tentative:
                continue
            raise AttributeError(
                f"Candidate '{candidate}' is missing required attribute '{name}'"
            )
        cand_attr = getattr(candidate, name)
        # If the interface expects a callable, ensure candidate provides one
        if callable(iface_attr):
            if not callable(cand_attr):
                if tentative:
                    continue
                raise TypeError(
                    f"Attribute '{name}' on candidate '{candidate}' "
                    f"should be callable like on interface '{iface}'"
                )
        # Optional: further type checks or signature validation could be added here
    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    try:
        # Ensure iface is a class or interface type
        if not isinstance(iface, type):
            raise TypeError("iface must be a class or interface type")

        # Resolve the candidate class (class or instance)
        impl = candidate if isinstance(candidate, type) else type(candidate)

        # If candidate already inherits from iface, it is acceptable
        if issubclass(impl, iface):
            return

        # Perform a lightweight duck‑typing check: all non‑dunder attributes defined
        for name in dir(iface):
            if name.startswith("__"):
                continue  # Skip magic methods
            if not hasattr(impl, name):
                if not tentative:
                    raise TypeError(
                        f"Candidate {impl.__name__} does not implement attribute '{name}' "
                        f"required by interface {iface.__name__}"
                    )
    except Exception as exc:
        raise TypeError(
            f"Invalid candidate {candidate!r} for interface {iface!r}: {exc}"
        ) from exc
    # If no exception was raised, verification passed. No explicit return needed.

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Helper to find the most derived common metaclass of two metaclasses
    def _common_meta(meta1, meta2):
        if meta1 is None:
            return meta2
        if meta2 is None:
            return meta1
        # Find earliest metaclass that is a supertype of both
        for m in meta1.__mro__:
            if m in meta2.__mro__:
                return m
        return None

    # If an explicit metaclass is supplied, it takes precedence
    # but it must be compatible with the bases.
    if explicit_mc is not None:
        # Verify explicit_mc is a metaclass (subclass of type)
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass {explicit_mc!r} is not a type")
        # Determine the common base metaclass of the bases
        base_meta = None
        for b in bases:
            if b is None:
                continue
            try:
                bm = b.__class__
            except Exception:
                bm = None
            base_meta = _common_meta(base_meta, bm)
        # If no bases or no common base, use type
        if base_meta is None:
            base_meta = type
        # Check compatibility
        if not issubclass(explicit_mc, base_meta):
            raise TypeError(
                f"Explicit metaclass {explicit_mc!r} is not compatible "
                f"with bases meta {base_meta!r}"
            )
        return explicit_mc

    # No explicit metaclass: derive from bases
    common_meta = None
    for b in bases:
        if b is None:
            continue
        try:
            meta = b.__class__
        except Exception:
            meta = None
        common_meta = _common_meta(common_meta, meta)

    # Default to 'type' if no bases or no shared metaclass
    return common_meta or type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate bases
    if not bases:
        # No bases provided; default to built-in type
        return type

    # Determine the base metaclass from the provided bases
    try:
        metaclass = type(bases[0])
    except Exception as exc:
        raise TypeError(f"Base {bases[0]!r} is not a class") from exc

    for base in bases[1:]:
        try:
            base_meta = type(base)
        except Exception as exc:
            raise TypeError(f"Base {base!r} is not a class") from exc

        if metaclass is base_meta:
            continue
        if issubclass(base_meta, metaclass):
            metaclass = base_meta
        elif issubclass(metaclass, base_meta):
            # keep existing metaclass
            pass
        else:
            raise TypeError(
                f"metaclass conflict between {metaclass.__name__} "
                f"and {base_meta.__name__}"
            )

    # If an explicit metaclass was provided, ensure it is compatible
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit __metaclass__ {explicit_mc!r} is not a type")
        # Determine the resulting metaclass: choose the most derived
        if issubclass(explicit_mc, metaclass):
            metaclass = explicit_mc
        elif issubclass(metaclass, explicit_mc):
            # keep current metaclass (the more derived one)
            pass
        else:
            raise TypeError(
                f"explicit __metaclass__ {explicit_mc.__name__} is not compatible with "
                f"base metaclasses {metaclass.__name__}"
            )

    return metaclass

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    try:
        del self[key]
    except KeyError:
        # The key disappeared between the get and delete
        if default is __marker:
            raise
        return default
    return value

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    del self[key]
    return value

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if default is __marker:
        return super().pop(key)
    return super().pop(key, default)

def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        # Ensure the underlying dictionary exists
        if not hasattr(self, "_data") or not isinstance(self._data, dict):
            raise AttributeError("Missing internal '_data' dictionary")
        if not hasattr(self, "_frequencies") or not isinstance(self._frequencies, dict):
            raise AttributeError("Missing internal '_frequencies' dictionary")

        # If the cache/dict is empty, raise KeyError to match dict.popitem()
        if not self._data:
            raise KeyError("popitem(): dictionary is empty")

        # Find the least frequently used key(s)
        try:
            min_freq = min(self._frequencies.values())
        except ValueError:
            # No frequencies recorded; fallback to arbitrary key removal
            min_freq = None

        # Gather all keys that have the minimal frequency
        if min_freq is not None:
            lfu_keys = [k for k, f in self._frequencies.items() if f == min_freq]
        else:
            lfu_keys = list(self._data.keys())

        # Selection strategy: if multiple keys share the same frequency, pick the
        # one that was inserted first.  The original order is preserved by
        # Python's dict insertion order (Python 3.7+).
        chosen_key = lfu_keys[0] if lfu_keys else None

        if chosen_key is None:
            # This should not happen, but guard against it
            raise KeyError("popitem(): unable to locate a key")

        value = self._data.pop(chosen_key)
        self._frequencies.pop(chosen_key, None)

        return (chosen_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    freq_map = None
    for attr in ('_freq', '_frequency', 'freq', 'frequency'):
        temp = getattr(self, attr, None)
        if isinstance(temp, dict):
            freq_map = temp
            break
    if freq_map and freq_map:
        min_freq = min(freq_map.values())
        min_key = next(k for k, f in freq_map.items() if f == min_freq)
        value = self.pop(min_key)
        try:
            del freq_map[min_key]
        except Exception:
            pass
        return (min_key, value)
    try:
        min_key = min(self, key=lambda k: self[k][0] if isinstance(self[k], (tuple, list)) else 0)
        value = self.pop(min_key)
        return (min_key, value)
    except Exception:
        k, v = super().popitem()
        return (k, v)

def popitem(self):
    """Remove and return the (key, value) pair least recently used."""
    # The least recently used item is the node just before the tail sentinel.
    node = self._tail[3]
    if node is self._head:
        raise KeyError('Cache is empty')
    self._find_lt(node[0])
    self._remove(node)
    return (node[0], node[1])

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # The least recently used item is the first real node after the head sentinel.
    node = self._head[2]
    if node is self._tail:  # the list is empty
        raise KeyError('Cache is empty')
    # Remove the node from the ordering and the main mapping.
    self._remove(node)
    key, value = node[0], node[1]
    # The key should also be removed from the dictionary that maps keys to nodes.
    # Some implementations may store the mapping under different attribute names; try common ones.
    for attr in ('_dict', '_mapping', '_store', '_data'):
        if hasattr(self, attr):
            try:
                del getattr(self, attr)[key]
            except KeyError:
                pass
            break
    return (key, value)

