    try:
        self._remove(node)
    except AttributeError:
        # Fallback removal if _remove not defined
        prev, key, value, nxt = node
        if prev is not None:
            prev[3] = nxt
        if nxt is not None:
            nxt[0] = prev
    return (node[1], node[2])

def popitem(self):
