    # the list is anchored by _head and _tail; empty list when they point to each other
    node = self._head[2]  # first real node after the sentinel head
    if node is self._tail:
        raise KeyError('LRU cache is empty')
    # find and remove the node
    self._find_lt(node[0])   # ensure we have correct prev link if needed
    self._remove(node)
    return (node[0], node[1])

