    except KeyError:
        raise KeyError('dictionary is empty')

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Attempt to pop the last item from an ordered collection that keeps
    # track of usage.  In most LRU implementations this is an `OrderedDict`
    # stored in `self._order`.  If the attribute does not exist, fall back to
    # a simple dict with a list of keys keeping usage ordering.
    try:
        # Preferred path: use an OrderedDict if available
        return self._order.popitem(last=True)
    except AttributeError:
        # Fallback: use a dict (`self._data`) and a list of keys (`self._usage`)
        if not hasattr(self, "_data") or not hasattr(self, "_usage"):
            raise KeyError("No storage attributes available for popitem")
        if not self._usage:
            raise KeyError("dict is empty")
        key = self._usage.pop()          # Most recently used key
        value = self._data.pop(key)      # Remove & return the value
        return key, value
    except KeyError:
        # OrderedDict was empty
        raise KeyError("dict is empty")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    node = self._head[2]  # Get the most recently used item
    if node is self._tail:
        raise KeyError('LRU is empty')
    self._remove(node)   # Detach node from the linked list
    return (node[0], node[1])

