def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    import datetime
    if not isinstance(dt, (datetime.datetime, datetime.date)):
        raise TypeError("dt must be a datetime.datetime or datetime.date instance")

    # Convert date to datetime at midnight if necessary
    if isinstance(dt, datetime.date) and not isinstance(dt, datetime.datetime):
        dt = datetime.datetime.combine(dt, datetime.time.min)

    # Convert to UTC if timezone aware
    if dt.tzinfo is not None:
        try:
            dt = dt.astimezone(datetime.timezone.utc)
        except Exception:
            # Fallback: pretend it's UTC
            pass

    # Format with milliseconds precision: YYYY-MM-DDTHH:MM:SS.mmmZ
    base = dt.strftime('%Y-%m-%dT%H:%M:%S')
    ms = int(dt.microsecond / 1000)
    return f"{base}.{ms:03d}Z"

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    # Regex to find URLs starting with http://, https:// or www.
    url_pattern = re.compile(r'\b((?:http[s]?://|www\.)\S+)', re.IGNORECASE)

    def _replace(match):
        try:
            url = match.group(0)
            href = url
            if href.lower().startswith('www.'):
                href = 'http://' + href
            # Add attributes to the link
            attrs = ' target="_blank" rel="noopener noreferrer"'
            return f'<a href="{href}"{attrs}>{url}</a>'
        except Exception:
            # In case of any unforeseen error, fall back to plain text
            return match.group(0)

    return url_pattern.sub(_replace, text)

