    url_re = re.compile(
        r'''(?i)\b((?:https?://|www\d{0,3}[.]|[a-z0-9.\-]+[.][a-z]{2,4}/)
        (?:[^\s()<>]+|\(([^\s()<>]+|(\([^\s()<>]+\)))*\))+
        (?:\(([^\s()<>]+|(\([^\s()<>]+\)))*\)|[^\s`!()\[\]{};:'".,<>?«»“”‘’]))'''
        , re.VERBOSE
    )

    def replace(match):
        url = match.group(0)
        href = url
        if not href.lower().startswith(('http://', 'https://')):
            href = 'http://' + href
        attrs = ' target="_blank" rel="noopener noreferrer"'
        return f'<a href="{href}"{attrs}>{url}</a>'

    return url_re.sub(replace, text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    if not isinstance(text, str):
        raise TypeError(f"Expected a string, got {type(text).__name__}")

    # Match URLs starting with http(s), ftp, or www.
    url_pattern = re.compile(r'\b((?:https?://|ftp://|www\.)[^\s<>"\'()]+)', re.IGNORECASE)

    def _replace(match):
        raw_url = match.group(1)
        href = raw_url
        # Prepend http:// to www URLs for proper href
        if raw_url.lower().startswith('www.'):
            href = f'http://{raw_url}'
        # Anchor tag with common security attributes
        return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{raw_url}</a>'

    try:
        return url_pattern.sub(_replace, text)
    except Exception as e:
        # Log or re-raise as needed; here we simply return original text on error
        return text

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        import urllib.request
        import urllib.parse
    except Exception:
        return None

    parsed = urllib.parse.urlparse(url)
    if parsed.scheme not in ('http', 'https'):
        return None

    req = urllib.request.Request(url, method='HEAD')
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            content_type = resp.headers.get('Content-Type')
            return content_type
    except Exception:
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        scheme, netloc, _, _, _ = urllib.parse.urlsplit(url)
        if scheme not in ("http", "https"):
            return None
        req = urllib.request.Request(url, headers={"Host": netloc}, method="HEAD")
        resp = urllib.request.urlopen(req)
        try:
            if resp.getcode() not in (200, None) and scheme not in ("ftp", "ftps"):
                return None
            return resp.info().get("Content-Type") or None
        finally:
            resp.close()
    except Exception:
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        # Parse URL and validate scheme
        scheme, netloc, path, query, fragment = urllib.parse.urlsplit(url)
        if scheme not in ('http', 'https', 'ftp', 'ftps'):
            return None

        # Build a HEAD request
        req = urllib.request.Request(url, method='HEAD')
        if netloc:
            req.add_header('Host', netloc)

        # Open URL
        with urllib.request.urlopen(req, timeout=10) as resp:
            if hasattr(resp, 'status') and resp.status not in (200, 301, 302, 303, 307, 308):
                return None
            return resp.info().get('Content-Type', None)
    except (urllib.error.URLError, urllib.error.HTTPError):
        return None
    except Exception:
        # Catch-all for any other unforeseen errors
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        # Accept only http/https URLs
        scheme = None
        if '://' in url:
            scheme = url.split('://', 1)[0].lower()
        if scheme not in ('http', 'https'):
            return None

        # Build a HEAD request
        req = Request(url, method='HEAD', headers={'User-Agent': 'Mozilla/5.0'})
        resp = urlopen(req, timeout=10)

        try:
            # Some servers may return 404/302 but still provide headers
            ct = resp.info().get('content-type')
            return ct if ct else None
        finally:
            try:
                resp.close()
            except Exception:
                pass
    except Exception:
        # Any failure (network, timeout, invalid URL) results in None
        return None

