    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation
    if not isinstance(url, str):
        raise TypeError(f"expected url to be a string, got {type(url).__name__}")
    if "://" not in url:
        raise ValueError(f"invalid URL format, missing scheme: {url}")

    # Strip trailing slash to ease path concatenation
    base = url.rstrip("/")

    # Determine the href for the NodeInfo document
    if document_path:
        # Ensure a leading slash
        if not document_path.startswith("/"):
            document_path = "/" + document_path
        href = base + document_path
    else:
        # Default path per NodeInfo spec
        href = f"{base}/.well-known/nodeinfo/1.0.json"

    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href,
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        import base64
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding
        from cryptography.exceptions import InvalidSignature
    except Exception:
        # cryptography library is not available
        return False

    # Load the public key.
    try:
        if isinstance(public_key, str):
            # Assume file path to PEM-formatted key.
            with open(public_key, 'rb') as f:
                key_data = f.read()
            pubkey = serialization.load_pem_public_key(key_data)
        else:
            # Assume a public key object is passed directly.
            pubkey = public_key
    except Exception:
        return False

    # Decode the signature.
    try:
        sig_bytes = base64.b64decode(signature)
    except Exception:
        return False

    # Prepare the data that was signed.
    if isinstance(doc, (bytes, bytearray)):
        data_bytes = bytes(doc)
    else:
        # Try to see if it's an XML element with tostring method.
        if hasattr(doc, 'tostring'):
            try:
                data_bytes = doc.tostring(encoding='utf-8')
            except Exception:
                data_bytes = str(doc).encode('utf-8')
        else:
            data_bytes = str(doc).encode('utf-8')

    # Perform signature verification.
    try:
        pubkey.verify(
            sig_bytes,
            data_bytes,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except InvalidSignature:
        return False
    except Exception:
        # Any other failure during verification is treated as invalid.
        return False

