def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        return None
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    # Fallback to XRD (XML)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        result: Dict[str, object] = {}
        # Subject
        subject = root.findtext("./Subject")
        if subject:
            result["subject"] = subject
        # Aliases
        aliases = [alias.text for alias in root.findall("./Alias") if alias.text]
        if aliases:
            result["aliases"] = aliases
        # Links
        links = []
        for link in root.findall("./Link"):
            rel = link.get("rel")
            href = link.get("href", "")
            type_attr = link.get("type")
            if rel:
                # rel may contain multiple values separated by spaces
                for r in [r.strip() for r in rel.split()]:
                    links.append({"rel": r, "href": href, "type": type_attr})
        if links:
            result["links"] = links
        return result
    except Exception:
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None

    # Attempt JSON parsing first
    try:
        data = json.loads(document)
        subject = data.get("subject")
        links = []
        for link in data.get("links", []):
            rel = link.get("rel")
            type_ = link.get("type")
            href = link.get("template") or link.get("href")
            if href:
                links.append({"rel": rel, "type": type_, "href": href})
        return {"subject": subject, "links": links}
    except Exception:
        # Not JSON, try XRD
        try:
            root = ET.fromstring(document)
        except Exception:
            # Cannot parse as XML either
            return None

        # Namespace-aware XPath; XRD namespace is common
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        subject_el = root.find(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject")
        subject = subject_el.text if subject_el is not None else None

        links = []
        for link_el in root.findall(
            ".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link"
        ):
            rel = link_el.attrib.get("rel")
            type_ = link_el.attrib.get("type")
            # XRD links may use 'href' or 'template'
            href = link_el.attrib.get("href") or link_el.attrib.get("template")
            if href:
                links.append({"rel": rel, "type": type_, "href": href})
        return {"subject": subject, "links": links}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result = {"subject": None, "aliases": [], "links": []}
    # First, try JSON
    try:
        data = json.loads(document)
        # Subject
        result["subject"] = data.get("subject")
        # Aliases
        aliases = data.get("aliases")
        if isinstance(aliases, list):
            result["aliases"] = aliases
        # Links
        links = data.get("links")
        if isinstance(links, list):
            for l in links:
                link_data = {"rel": l.get("rel")}
                if "href" in l:
                    link_data["href"] = l["href"]
                if "type" in l:
                    link_data["type"] = l["type"]
                if "title" in l:
                    link_data["title"] = l["title"]
                if "template" in l:
                    link_data["template"] = l["template"]
                result["links"].append(link_data)
        return result
    except Exception:
        # Not JSON, try XRD (XML)
        try:
            root = ET.fromstring(document)
            # Subject
            subj = root.find(".//{*}Subject") or root.find("Subject")
            if subj is not None and subj.text:
                result["subject"] = subj.text
            # Aliases
            aliases = root.findall(".//{*}Alias") or root.findall("Alias")
            for a in aliases:
                if a.text:
                    result["aliases"].append(a.text)
            # Links
            links = root.findall(".//{*}Link") or root.findall("Link")
            for l in links:
                rel = l.attrib.get("rel")
                if not rel:
                    continue
                link_entry = {"rel": rel}
                if "href" in l.attrib:
                    link_entry["href"] = l.attrib["href"]
                if "type" in l.attrib:
                    link_entry["type"] = l.attrib["type"]
                if "title" in l.attrib:
                    link_entry["title"] = l.attrib["title"]
                if "template" in l.attrib:
                    link_entry["template"] = l.attrib["template"]
                result["links"].append(link_entry)
            return result
        except Exception:
            # Unable to parse
            return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return {}

    # try JSON webfinger
    try:
        data = json.loads(document)
        links = data.get("links", [])
        result: Dict[str, str] = {}
        for link in links:
            href = link.get("href")
            rel = link.get("rel")
            if not href or not rel:
                continue
            if rel == "http://webfinger.net/rel/hcard":
                result["hcard_url"] = href
            elif rel == "lrdd":
                result["lrdd_url"] = href
            else:
                # generic key for other relations
                key = f"rel_{rel.replace('http://', '').replace('/', '_').replace(':', '')}"
                result[key] = href
        if result:
            return result
    except Exception:
        pass  # fall back to XRD parsing

    # try XRD (old) webfinger
    try:
        root = ElementTree.fromstring(document)
        # namespace-agnostic XPath
        for link in root.findall(".//{*}Link"):
            href = link.get("href")
            rel = link.get("rel")
            if not href or not rel:
                continue
            if rel == "http://webfinger.net/rel/hcard":
                return {"hcard_url": href}
            elif rel == "lrdd":
                return {"lrdd_url": href}
            else:
                key = f"rel_{rel.replace('http://', '').replace('/', '_').replace(':', '')}"
                return {key: href}
    except Exception:
        pass

    return {}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # Ensure handle contains a host part
        handle = handle.strip()
        if not handle or '@' not in handle:
            return None

        host = handle.split('@', 1)[1]
        resource = f"acct:{handle}"
        from urllib.parse import quote_plus
        url = f"https://{host}/.well-known/webfinger?resource={quote_plus(resource)}"

        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                return None
            return resp.read().decode('utf-8')
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Validate and extract host
    try:
        host = handle.split("@")[1]
    except Exception:
        return None

    # Build the RFC7033 webfinger URL
    url = "https://{0}/.well-known/webfinger?resource=acct:{1}".format(host, handle)

    # Attempt retrieval over HTTPS
    try:
        page = urllib2.urlopen(url)
    except Exception:
        # Fallback to HTTP if HTTPS fails
        alt_url = "http://{0}/.well-known/webfinger?resource=acct:{1}".format(host, handle)
        try:
            page = urllib2.urlopen(alt_url)
        except Exception:
            return None
    else:
        pass

    # Read and return the document
    try:
        data = page.read()
        if isinstance(data, bytes):
            data = data.decode("utf-8", errors="ignore")
        return data
    except Exception:
        return None
    finally:
        try:
            page.close()
        except Exception:
            pass

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split('@', 1)[1]
    except Exception:
        return None
    resource = f"acct:{handle}"
    try:
        resource_enc = urllib.parse.quote(resource, safe='')
    except Exception:
        resource_enc = urllib.parse.quote(resource, safe='')
    url = f"https://{host}/.well-known/webfinger?resource={resource_enc}"
    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            if getattr(resp, 'status', 200) != 200:
                return None
            charset = resp.headers.get_content_charset('utf-8')
            return resp.read().decode(charset)
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # Normalise handle to `acct:` form
        if handle.startswith("acct:"):
            acct = handle[5:]
        else:
            acct = handle

        if "@" not in acct:
            return None
        user, host = acct.split("@", 1)

        # Construct the resource query parameter
        resource = f"acct:{user}@{host}"
        query = urllib.parse.urlencode({"resource": resource})

        # Build the well‑known URL
        url = f"https://{host}/.well-known/webfinger?{query}"
        try:
            response = urllib.request.urlopen(url, timeout=10)
        except urllib.error.HTTPError as e:
            if e.code in (404, 410, 406):
                return None
            raise
        except urllib.error.URLError:
            # Fallback to http if https fails
            url = f"http://{host}/.well-known/webfinger?{query}"
            try:
                response = urllib.request.urlopen(url, timeout=10)
            except Exception:
                return None
        content = response.read()
        return content.decode("utf-8")
    except Exception:
        return None

