def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch

    # Accept single directory or iterable of directories
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)

    filenames = []

    for d in dirs:
        try:
            for entry in os.listdir(d):
                full_path = os.path.join(d, entry)
                if not os.path.isfile(full_path):
                    continue

                if spec_option is None:
                    filenames.append(full_path)
                else:
                    # If spec_option is a string, treat it as a pattern with fnmatch
                    if isinstance(spec_option, str):
                        if fnmatch.fnmatch(entry, spec_option):
                            filenames.append(full_path)
                    else:
                        # Assume callable: try to use it as a predicate on the filename
                        try:
                            if spec_option(entry):
                                filenames.append(full_path)
                        except Exception:
                            # Skip if predicate raises an error
                            continue
        except Exception:
            # Skip directories that cannot be accessed
            continue

    return sorted(filenames)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    try:
        if not settings_dirs:
            return []

        # Allow a single string directory
        if isinstance(settings_dirs, str):
            settings_dirs = [settings_dirs]

        import os
        import fnmatch

        files = []
        for dir_path in settings_dirs:
            try:
                for fname in os.listdir(dir_path):
                    # If a spec_option is supplied, filter by it
                    if spec_option:
                        if isinstance(spec_option, str):
                            pattern = spec_option
                        else:
                            # Unsupported spec_option type; skip filtering
                            pattern = None
                        if pattern and not fnmatch.fnmatch(fname, pattern):
                            continue
                    files.append(os.path.join(dir_path, fname))
            except OSError:
                # Skip directories that cannot be accessed
                continue

        return sorted(files)
    except Exception:
        return []

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    try:
        if isinstance(settings_dirs, str):
            dirs = [settings_dirs]
        else:
            dirs = list(settings_dirs)
        if not dirs:
            return []

        pattern = spec_option if spec_option else '*.ini'

        files = []
        for directory in dirs:
            if not os.path.isdir(directory):
                continue
            for root, _, fnames in os.walk(directory):
                for fname in fnames:
                    if fnmatch.fnmatch(fname, pattern):
                        files.append(os.path.join(root, fname))
        return sorted(files)
