        # emit deprecation warnings and optionally migrate the values.
        deprecated_map = getattr(self, "deprecated_args", None)
        if isinstance(deprecated_map, dict):
            for old_arg, new_arg in deprecated_map.items():
                # Check CLI arguments
                if old_arg in cli_args:
                    warnings.warn(
                        f'Keyword argument "{old_arg}" has been deprecated in favour '
                        f'of "{new_arg}".',
