def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")

    # Retrieve the command's option list
    try:
        options = self.commands[command_name]
    except KeyError:
        # Command not found
        return None

    # Search for the option specification by name
    for opt in options:
        # Option might be stored as a dict
        if isinstance(opt, dict):
            if opt.get("name") == argument_name:
                return opt
        else:
            # Assume it's an object with a 'name' attribute or property
            opt_name = getattr(opt, "name", None)
            if opt_name == argument_name:
                return opt

    # If no matching option spec is found, return None
    return None

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not hasattr(self, 'commands'):
        raise AttributeError("'self' object has no attribute 'commands'")

    try:
        command = self.commands[command_name]
    except (KeyError, TypeError):
        raise ValueError(f"Command '{command_name}' does not exist")

    # The command may expose its option specifications in several common ways.
    # First, try the 'options' key if present.
    options = None
    if isinstance(command, dict):
        options = command.get('options')
    elif hasattr(command, 'options'):
        options = getattr(command, 'options')
    else:
        raise ValueError(f"Command '{command_name}' has no option specification")

    # Normalize options to a list of spec dicts.
    if options is None:
        raise ValueError(f"Command '{command_name}' has no options defined")

    if isinstance(options, dict):
        # Direct dictionary mapping names to specs
        spec = options.get(argument_name)
        if spec is not None:
            return spec
        # Try aliases
        for key, value in options.items():
            aliases = value.get('aliases', [])
            if isinstance(aliases, (list, tuple)) and argument_name in aliases:
                return value
    elif isinstance(options, (list, tuple)):
        # List of spec dicts
        for opt_spec in options:
            if not isinstance(opt_spec, dict):
                continue
            name = opt_spec.get('name')
            if name == argument_name:
                return opt_spec
            aliases = opt_spec.get('aliases', [])
            if isinstance(aliases, (list, tuple)) and argument_name in aliases:
                return opt_spec

    # If we reach here, the option was not found
    raise ValueError(f"Option '{argument_name}' not found for command '{command_name}'")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Basic validation of input arguments
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise ValueError("Both command_name and argument_name must be strings")

    # Try to locate the command specification
    try:
        command_spec = self._specs[command_name]
    except (AttributeError, KeyError):
        raise KeyError(f"Command '{command_name}' not found in specifications")

    # The command specification is expected to be a mapping of option names to their specs
    try:
        option_spec = command_spec[argument_name]
    except KeyError:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")

    return option_spec

