def get_silent_args(self, args):
    """List of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    # Ensure args is iterable
    if args is None:
        return []
    try:
        iterator = iter(args)
    except TypeError as exc:
        raise TypeError('args must be an iterable of strings') from exc

    silent_args = []
    seen = set()
    for arg in iterator:
        if not isinstance(arg, str):
            continue
        # Recognize end-of-args marker
        if arg == '--':
            break
        if arg.startswith('-'):
            if arg not in seen:
                silent_args.append(arg)
                seen.add(arg)
    return silent_args

