    silent_args = []
    try:
        # If args is an argparse.Namespace or a dict-like object
        if hasattr(args, "__dict__") or isinstance(args, dict):
            # Convert to dict-like representation
            kwargs = vars(args) if hasattr(args, "__dict__") else args
            for key, value in kwargs.items():
                # Include any flag-like names (start with a dash) or boolean flags
                if isinstance(key, str) and key.startswith("-"):
                    silent_args.append(key)
                elif isinstance(value, bool):
                    silent_args.append(key)
        else:
            # Assume iterable of strings (e.g., sys.argv or similar)
            for item in args:
                if isinstance(item, str) and item.startswith("-"):
                    silent_args.append(item)
    except Exception:
        # On any unexpected error, gracefully return an empty list
        return []

    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the list of required argument identifiers.
    required = getattr(self, 'required', [])
    if not required:
        # Nothing to validate.
        return

    missing = []

    if args is None:
        # All required arguments are missing.
        missing.extend(required)
    elif isinstance(args, dict):
        # Positional arguments are stored as a mapping of names to values.
        for name in required:
            # A required key is missing if it is not present or its value is None.
            if name not in args or args[name] is None:
                missing.append(name)
    else:
        # Assume the arguments are passed as a sequence (tuple, list, etc.).
        # In this case, we expect required to be a list of positions (integers).
        # Anything that cannot be interpreted as a position will be ignored.
        for pos in required:
            if isinstance(pos, int):
                if pos < 0 or pos >= len(args):
                    missing.append(str(pos))
            else:
                # If the required value is not an integer, we cannot
                # determine its presence in a sequence; skip it.
                continue

    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(map(str, missing))}")

