def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is an iterable
    try:
        iter(args)
    except TypeError:
        raise TypeError("args must be an iterable of values")

    # Determine the bounds from the instance; allow multiple naming conventions
    min_val = getattr(self, "min_", None) or getattr(self, "min", None)
    max_val = getattr(self, "max_", None) or getattr(self, "max", None)

    # If neither bound is provided, nothing to validate
    if min_val is None and max_val is None:
        return args

    # Validate each value in the iterable
    for idx, val in enumerate(args):
        # Skip non-numeric values
        if not isinstance(val, (int, float, complex)):
            continue

        if min_val is not None and val < min_val:
            raise ValueError(
                f"Argument at position {idx} with value {val} is below the minimum of {min_val}"
            )
        if max_val is not None and val > max_val:
            raise ValueError(
                f"Argument at position {idx} with value {val} exceeds the maximum of {max_val}"
            )

    return args

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        # Ensure that args is a mapping of argument names to their values.
        if not isinstance(args, dict):
            raise TypeError(f"args must be a dict, got {type(args).__name__}")

        # Retrieve optional min/max dictionaries if defined on the instance.
        min_values = getattr(self, "min_values", {})
        max_values = getattr(self, "max_values", {})

        for name, value in args.items():
            # Attempt to determine the minimum for this argument.
            min_val = None
            if hasattr(self, f"min_{name}"):
                min_val = getattr(self, f"min_{name}")
            elif isinstance(min_values, dict):
                min_val = min_values.get(name)
            if min_val is not None and value < min_val:
                raise ValueError(
                    f"Argument '{name}' value {value} is less than the minimum {min_val}"
                )

            # Attempt to determine the maximum for this argument.
            max_val = None
            if hasattr(self, f"max_{name}"):
                max_val = getattr(self, f"max_{name}")
            elif isinstance(max_values, dict):
                max_val = max_values.get(name)
            if max_val is not None and value > max_val:
