                )

        # All values passed the checks.
        return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Resolve the minimum and maximum constraints
    min_val = getattr(self, "min_value", None)
    if min_val is None:
        min_val = getattr(self, "min_", None)
    max_val = getattr(self, "max_value", None)
    if max_val is None:
        max_val = getattr(self, "max_", None)

    if min_val is None and max_val is None:
        raise ValueError("Neither minimum nor maximum values were set for validation")

    # Ensure args is iterable
    try:
        iter(args)
    except TypeError:
        raise TypeError("Provided args must be an iterable")

    for idx, value in enumerate(args):
        # Skip None values silently (they are considered missing)
        if value is None:
            continue
        # Try to compare; raise clear error if incomparable
        try:
            if min_val is not None and value < min_val:
                raise ValueError(
                    f"Argument at position {idx} = {value} is below minimum {min_val}"
                )
            if max_val is not None and value > max_val:
                raise ValueError(
                    f"Argument at position {idx} = {value} exceeds maximum {max_val}"
                )
        except TypeError as exc:
            raise TypeError(
                f"Argument at position {idx} = {value} cannot be compared with "
                f"minimum {min_val} and maximum {max_val}"
            ) from exc

    return args

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is an iterable and not a string
    if isinstance(args, (str, bytes)):
        raise TypeError("args must not be a string or bytes")
    try:
        values = list(args)
    except TypeError as exc:
        raise TypeError("args must be iterable") from exc

    if len(values) != 3:
        raise ValueError("expected 3 arguments: value, min, max; got %d" % len(values))

    value, minimum, maximum = values

    # Validate that min and max are provided and correctly ordered
    try:
        if minimum > maximum:
            raise ValueError("minimum value (%r) must be less than or equal to maximum value (%r)" % (minimum, maximum))
    except TypeError as exc:
        raise TypeError("minimum and maximum must be comparable types") from exc

    # Validate value against bounds
    try:
        if value < minimum:
            raise ValueError("value (%r) is less than minimum (%r)" % (value, minimum))
        if value > maximum:
            raise ValueError("value (%r) is greater than maximum (%r)" % (value, maximum))
    except TypeError as exc:
        raise TypeError("value and bounds must be comparable types") from exc

    # Return the validated value (optional)
    return value

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Validate inputs
    if not subcommand or not isinstance(subcommand, str):
        raise ValueError(f"Invalid subcommand: {subcommand!r}")
    if not type_name or not isinstance(type_name, str):
        raise ValueError(f"Invalid type_name: {type_name!r}")
    if not option_name or not isinstance(option_name, str):
        raise ValueError(f"Invalid option_name: {option_name!r}")
    if spec_option is None:
        raise ValueError("spec_option cannot be None")

    # Determine the actual callable/type that will be used
    if isinstance(spec_option, dict) and "__type__" in spec_option:
        # Use the generic construct helper that expects a mapping with '__type__'
        try:
            arg_type = self.construct(spec_option)
        except Exception as exc:
            raise ValueError(
                f"Failed to construct complex type '{type_name}' for option "
                f"'{option_name}' in subcommand '{subcommand}': {exc}"
            ) from exc
    elif callable(spec_option):
        arg_type = spec_option
    else:
        raise TypeError(
            f"Unsupported spec_option type for complex argument type "
            f"'{type_name}': {type(spec_option).__name__}"
        )

    # Store the type in a registry (if the instance has such an attribute)
    registry = getattr(self, "_complex_types", None)
    if registry is None:
        registry = {}
        self._complex_types = registry
    registry[(subcommand, type_name)] = arg_type

    return arg_type

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary")
    from types import SimpleNamespace
    namespace = {
        'subcommand': subcommand,
        'type_name': type_name,
        'option_name': option_name
    }
    namespace.update(spec_option)
    return SimpleNamespace(**namespace)

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications (a mapping)
    :return: the complex type instance
    """
    try:
        # Build a dynamic class name that is unique per subcommand and type
        class_name = f"{type_name}_{subcommand}"
        # Default constructor that simply stores all keyword arguments as attributes
        def _constructor(self, **kwargs):
            for k, v in kwargs.items():
                setattr(self, k, v)
        # Create the class dynamically
        ComplexType = type(class_name, (object,), {"__init__": _constructor})
        # If spec_option is not a mapping, try to convert or use empty dict
        if not isinstance(spec_option, dict):
            spec_option = {}
        # Optionally attach metadata about option_name for debugging reference
        spec_option["_option_name"] = option_name
        return ComplexType(**spec_option)
    except Exception as exc:
        raise ValueError(
            f"Failed to create complex argument type '{type_name}' for subcommand '{subcommand}': {exc}"
        ) from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    import argparse
    import json
    from collections import namedtuple

    # Extract any custom 'fields' specification used for building a NamedTuple
    # and prepare a clean argument dictionary for argparse.
    fields = spec_option.get('fields')
    arg_options = {k: v for k, v in spec_option.items() if k != 'fields'}

    if fields:
        # Build a simple NamedTuple type for the parsed value
        ComplexType = namedtuple(type_name, fields)

        def type_parser(value):
            try:
                parts = [p.strip() for p in value.split(',')]
                if len(parts) != len(fields):
                    raise ValueError(
                        f"Expected {len(fields)} comma-separated values for {option_name}"
                    )
                return ComplexType(*parts)
            except Exception as exc:
                raise argparse.ArgumentTypeError(
                    f"Invalid value for {option_name}: {exc}"
                )

    else:
        # Default to parsing JSON string into a Python dict/list
        def type_parser(value):
            try:
                return json.loads(value)
            except Exception as exc:
                raise argparse.ArgumentTypeError(
                    f"Invalid JSON for {option_name}: {exc}"
                )

    # Register the argument with the subcommand, if possible
    try:
        subcommand.add_argument(option_name, type=type_parser, **arg_options)
    except Exception:
        # If subcommand is not an argparse parser, silently ignore
        pass

    return type_parser

def get_nested_custom_and_control_args(self, args):
    """Split input arguments into control and nested arguments.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: a dictionary of collected command‑line arguments.
    :return: tuple of two flat dictionaries (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Defensive check: ensure we have a mapping to iterate over
    if args is None:
        return control_args, nested_args
    if not isinstance(args, dict):
        # If args is not a dict, we cannot split it reliably.
        raise TypeError(
            f"Expected args to be a dict, got {type(args).__name__}"
        )

    for key, value in args.items():
        if not isinstance(key, str):
            # Skip non‑string keys – they cannot be processed
            continue
        # Normalize key for comparison
        key = key.strip()
        if key.startswith("control."):
            # Remove the prefix and store in control dict
            control_key = key[len("control.") :]
            control_args[control_key] = value
        elif key.startswith("custom."):
