    if isinstance(args, dict):
        items = args.items()
    else:
        items = []
        for item in args:
            if isinstance(item, tuple) and len(item) == 2:
                key, value = item
                items.append((key, value))
            elif isinstance(item, str) and '=' in item:
                # parse key=value string
                key, value = item.split('=', 1)
