    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: Extra vars that can be a dict, list of dicts, strings or comma separated key=value pairs
    :return: The updated vars_dict
    """
    # Ensure vars_dict is a dictionary; if None start with empty dict
    if vars_dict is None:
        vars_dict = {}
    elif not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")

    # Nothing to merge
    if not extra_vars:
        return vars_dict

    # Helper function to merge a single mapping into vars_dict
    def _merge_mapping(mapping):
        if isinstance(mapping, dict):
            vars_dict.update(mapping)
        else:
            raise TypeError("Each item must be a dict")

    # Process based on type of extra_vars
    if isinstance(extra_vars, dict):
        _merge_mapping(extra_vars)
    elif isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                _merge_mapping(item)
            elif isinstance(item, str):
                if '=' in item:
                    key, _, value = item.partition('=')
                    vars_dict[key] = value
                else:
                    # ignore unparseable strings
                    continue
            else:
                # ignore unexpected item types
                continue
    elif isinstance(extra_vars, str):
        for part in extra_vars.split(','):
            if '=' in part:
                key, _, value = part.partition('=')
                vars_dict[key] = value
    else:
        raise TypeError("extra_vars must be a dict, list, or string")

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: A new dictionary containing the merged variables.
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")

    if extra_vars is None:
        return vars_dict

    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list or tuple of mappings")

    merged = vars_dict.copy()
    for item in extra_vars:
        if isinstance(item, dict):
            merged.update(item)
        else:
            raise TypeError("Each item in extra_vars must be a dict")
    return merged

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    import os

    command = ['ansible-playbook']

    # Add verbosity if specified
    if verbose is not None:
        if isinstance(verbose, int) and verbose > 0:
            command.append('-' * verbose)
        elif isinstance(verbose, str):
            command.append(verbose)

    # Resolve playbook path relative to workspace if not absolute
    if not os.path.isabs(playbook_path):
        base_dir = getattr(ir_workspace, 'root', '.')
        playbook_path = os.path.join(base_dir, playbook_path)
    command.append(playbook_path)

    # Add custom ansible-playbook arguments
    if ansible_args:
        for key, val in ansible_args.items():
            if isinstance(val, bool):
                if val:
                    command.append(f'--{key}')
            else:
                command.append(f'--{key}={val}')

    # Add extra variables
    if extra_vars:
        try:
            json_vars = json.dumps(extra_vars)
            command.extend(['--extra-vars', json_vars])
        except (TypeError, ValueError):
            vars_str = ' '.join(f'{k}={v}' for k, v in extra_vars.items())
            command.extend(['--extra-vars', vars_str])

    # Debug logging if available
    logger = getattr(ir_workspace, 'logger', None)
    if logger:
        logger.debug('Executing ansible-playbook command: %s', ' '.join(command))

    try:
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            check=True,
        )
        output = result.stdout
        if logger:
            logger.debug('ansible-playbook output: %s', output.strip())
        return output
    except subprocess.CalledProcessError as exc:
        error_msg = exc.stderr or str(exc)
        raise RuntimeError(f"ansible-playbook failed: {error_msg}") from exc

