def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Attempt to locate parser configuration which holds expected types.
    # The structure may vary, but first try a direct attribute lookup.
    parser_cfg = None
    try:
        parser_cfg = getattr(self, parser_name, None)
    except Exception:
        parser_cfg = None

    # If parser_cfg is not a dict, look for a common attribute that might hold
    # option definitions (e.g., 'options', 'args', or 'arg_definitions').
    if not isinstance(parser_cfg, dict):
        # Common fallback attributes
        for attr in ("options", "args", "arg_definitions"):
            if hasattr(self, attr):
                possible = getattr(self, attr)
                if isinstance(possible, dict) and parser_name in possible:
                    parser_cfg = possible[parser_name]
                    break

    # If we still couldn't find a suitable config, nothing to convert.
    if not isinstance(parser_cfg, dict):
        return

    # Helper to resolve a conversion function from a descriptor.
    def _converter_from_def(definition):
        # definition might be a dict containing a 'type' key or a callable.
        if callable(definition):
            return definition
        if isinstance(definition, dict):
            type_val = definition.get("type")
            if callable(type_val):
                return type_val
            if isinstance(type_val, str):
                # map common string names to actual types
                type_str = type_val.lower()
                if type_str in ("int", "integer"):
                    return int
                if type_str in ("float", "double"):
                    return float
                if type_str in ("bool", "boolean"):
                    # interpret truthy/falsy strings
                    return lambda v: v.lower() in ("1", "true", "yes", "on")
                if type_str in ("list", "lst", "tuple"):
                    # comma separated list
                    return lambda v: [x.strip() for x in v.split(",") if x]
                if type_str in ("dict", "dictionary"):
                    # simple JSON style
                    import json
                    return lambda v: json.loads(v)
                # default fallback: leave string
                return lambda v: v
        # If not recognized, preserve original
        return lambda v: v

    # Iterate over the argument keys present in the values_dict.
    for key, raw_value in list(values_dict.items()):
        # Skip if raw_value is already a non-string (unlikely but safe)
        if not isinstance(raw_value, str):
            continue

        # Look up the expected definition for this key in the parser config.
        definition = None
        if key in parser_cfg:
            definition = parser_cfg[key]
        else:
            # Some configs may store definitions under a nested structure like 'arguments'
            nested = parser_cfg.get("arguments")
            if isinstance(nested, dict):
                definition = nested.get(key)

        # If we found a definition, convert using its converter.
        converter = _converter_from_def(definition)
        if converter is None:
            # No conversion information; skip this key.
            continue

        try:
            converted = converter(raw_value)
            if converted is not None:
                values_dict[key] = converted
        except Exception:
            # If conversion fails, silently retain the original string.
            pass

