        val_lower = val.lower()
        if val_lower in {'true', 't', 'yes', 'y', '1'}:
            return True
        if val_lower in {'false', 'f', 'no', 'n', '0'}:
            return False
        return None

    def _to_number(val):
        try:
            return int(val)
        except ValueError:
            pass
        try:
            return float(val)
        except ValueError:
            return None

    for key, raw_val in list(values_dict.items()):
        # ignore None or empty values
        if raw_val is None or raw_val == '':
            continue

        # Boolean conversion
        bool_val = _to_bool(str(raw_val))
        if bool_val is not None:
            values_dict[key] = bool_val
            continue

        # List conversion – comma separated
        if isinstance(raw_val, str) and ',' in raw_val:
            parts = raw_val.split(',')
            converted_parts = []
            for part in parts:
                part = part.strip()
                num_val = _to_number(part)
                if num_val is not None:
                    converted_parts.append(num_val)
                else:
                    # keep as string
                    converted_parts.append(part)
            values_dict[key] = converted_parts
            continue

        # Single numeric conversion
        num_val = _to_number(str(raw_val))
        if num_val is not None:
            values_dict[key] = num_val
            continue

        # Remaining values stay as string
        values_dict[key] = str(raw_val)

