def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of arguments
    """
    # Attempt to retrieve the option collection for the given parser.
    # The exact attribute name may vary; common patterns are
    #   self.parsers[parser_name]
    #   self.options[parser_name]
    # Each option object is expected to expose `name` and either
    # `convert` or `type` callable for type casting.
    options = []

    if hasattr(self, "parsers"):
        parser_obj = self.parsers.get(parser_name)
        if parser_obj:
            options = getattr(parser_obj, "options", [])
            if not options:
                options = getattr(parser_obj, "args", [])
    if not options and hasattr(self, "options"):
        options = self.options.get(parser_name, [])

    # If we still have no option list, nothing to convert.
    if not options:
        return

    for opt in options:
        # Resolve the name of the option.
        name = getattr(opt, "name", None)
        if not name or name not in values_dict:
            continue

        raw_val = values_dict[name]

        # Determine the converter function.
        if hasattr(opt, "convert") and callable(opt.convert):
            converter = opt.convert
        elif hasattr(opt, "type") and callable(opt.type):
            converter = opt.type
        else:
            # Fall back to string conversion (no-op).
            converter = str

        try:
            # Handle list values by converting each element.
            if isinstance(raw_val, list):
                values_dict[name] = [converter(v) for v in raw_val]
            else:
                values_dict[name] = converter(raw_val)
        except Exception:
            # Silently ignore conversion errors; keep the original value.
            pass

