    if spec_file is None:
        raise FileNotFoundError(f"No spec file found in {plugin_dir}")

    try:
        with open(spec_file, 'r', encoding='utf-8') as fh:
            if spec_file.endswith('.json'):
                spec_data = json.load(fh)
            else:
                spec_data = yaml.safe_load(fh)
    except Exception as exc:
        raise ValueError(f"Failed to read spec file {spec_file}: {exc}") from exc

    if not isinstance(spec_data, dict):
        raise ValueError(f"Spec file {spec_file} does not contain a dictionary")

    flat_dict = _flatten_dict(spec_data)
    return flat_dict}

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    # Try to locate a spec file in common formats
    spec_files = ["plugin.yml", "plugin.yaml", "plugin.json",
                  "spec.yml", "spec.yaml", "spec.json"]
    spec_path = None
    for filename in spec_files:
        candidate = os.path.join(plugin_dir, filename)
        if os.path.isfile(candidate):
            spec_path = candidate
            break
    if not spec_path:
        return {}
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.endswith(".json"):
                data = json.load(f)
            else:
                # Defer import of yaml until needed; handle missing dependency gracefully
                try:
                    import yaml
                except Exception:
                    return {}
                data = yaml.safe_load(f)
    except Exception:
        # In case of any IO or parsing error, return empty dict
        return {}

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key=""):
        flat = {}
        for key, value in d.items():
            full_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                flat.update(_flatten(value, full_key))
            else:
                flat[full_key] = value
        return flat

    try:
        return _flatten(data)
    except Exception:
        return {}

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:  # pragma: no cover
        yaml = None

    # Attempt to locate the spec file
    spec_file = None
    for candidate in ("plugin.json", "plugin.yaml", "plugin.yml",
                      "spec.json", "spec.yaml", "spec.yml"):
        path = os.path.join(plugin_dir, candidate)
        if os.path.isfile(path):
            spec_file = path
            break

    # Fallback: any json/.yaml/.yml in directory
    if spec_file is None:
        for fname in os.listdir(plugin_dir):
            if fname.endswith((".json", ".yaml", ".yml")):
                spec_file = os.path.join(plugin_dir, fname)
                break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin specification found in {plugin_dir}")

    # Load the spec
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith(".json"):
                spec_dict = json.load(f)
            elif yaml is not None and spec_file.endswith((".yaml", ".yml")):
                spec_dict = yaml.safe_load(f)
            else:
                raise ValueError(f"Unsupported spec file type: {spec_file}")
    except Exception as exc:  # pragma: no cover
        raise RuntimeError(f"Failed to load plugin spec from {spec_file}") from exc

    # Recursive flatten
    def _flatten(obj, parent_key="", sep="."):
        result = {}
        for key, value in obj.items():
            new_key = f"{parent_key}{sep}{key}" if parent_key else key
            if isinstance(value, dict):
                result.update(_flatten(value, new_key, sep=sep))
            else:
                result[new_key] = value
        return result

    return _flatten(spec_dict)

